// ===== Vize maliyet kalemleri (kategori bazlı) =====
const VISA_COST_CATEGORIES = [
  { id: 'schengen', label: 'Schengen', icon: '🇪🇺' },
  { id: 'russia', label: 'Rusya', icon: '🇷🇺' },
  { id: 'uae', label: 'BAE (Dubai)', icon: '🇦🇪' },
  { id: 'usa', label: 'Amerika', icon: '🇺🇸' },
  { id: 'uk', label: 'İngiltere', icon: '🇬🇧' },
  { id: 'china', label: 'Çin', icon: '🇨🇳' },
  { id: 'other', label: 'Diğer', icon: '🌍' }
];
const DEFAULT_VISA_COST_ITEMS = [
  { key: 'konsolosluk', label: 'Konsolosluk Bedeli' },
  { key: 'araci', label: 'Aracı Hizmet Bedeli' },
  { key: 'sigorta', label: 'Sigorta' },
  { key: 'vfs', label: 'iData / VFS Hiz. Bed.' },
  { key: 'koordinasyon', label: 'Koordinasyon' },
  { key: 'sms', label: 'SMS' },
  { key: 'kargo', label: 'Kargo' },
  { key: 'kdv', label: 'KDV' },
  { key: 'diger', label: 'Diğer' }
];
// visaCostItems iki biçimde olabilir: eski düz dizi [...] veya kategori bazlı { schengen: [...], usa: [...] }
const getVisaCostItems = (appSettings, category) => {
  const raw = appSettings?.visaCostItems;
  if (Array.isArray(raw)) return raw.length ? raw : DEFAULT_VISA_COST_ITEMS;
  const list = raw && raw[category || 'schengen'];
  return Array.isArray(list) && list.length ? list : DEFAULT_VISA_COST_ITEMS;
};
// Yeni başvuru için varsayılan maliyetler: kategori varsayılanı + (varsa) o vize türüne özel değerler
const getVisaCostDefaults = (appSettings, category, typeName) => ({
  ...((appSettings?.visaCostDefaults || {})[category] || {}),
  ...(typeName ? (((appSettings?.visaCostTypeDefaults || {})[category] || {})[typeName] || {}) : {})
});
// Bir başvurunun maliyetlerini para birimi bazında toplar. Kalem listesinden bağımsız olarak
// kayıttaki tüm tutarları sayar — ayarlardan kaldırılan bir kalem kâr/zarardan düşmesin.
const sumVisaCosts = (visa) => {
  const cur = visa?.costCurrency || visa?.visaCurrency || visa?.currency || '€';
  const total = Object.values(visa?.costs || {}).reduce((t, v) => t + (parseFloat(v) || 0), 0);
  return total ? { [cur]: total } : {};
};

// ===== SÖZLEŞME: paylaşılan üreticiler (QuotesModule + ToursModule) =====
const trTarih = (iso) => { if (!iso) return ''; const [y,m,d] = iso.split('-'); return `${d}/${m}/${y}`; };
const contractSure = (c) => {
  if (!c.startDate || !c.endDate) return '';
  const a = new Date(c.startDate + 'T00:00:00'), b = new Date(c.endDate + 'T00:00:00');
  const gece = Math.round((b - a) / 86400000);
  if (isNaN(gece) || gece < 0) return '';
  return `${gece} Gece ${gece + 1} Gündür`;
};
const vizeSartiBul = (ulke) => {
  const d = VIZE_DURUM[ulke];
  if (!d) return { metin: '', bilinmiyor: true, detay: '' };
  if (d.b === 'yurtici') return { metin: 'Vize şartı bulunmamaktadır.', bilinmiyor: false, detay: d.t };
  if (d.b === 'tabi') return { metin: `${ulke} Vizesi Şartı bulunmaktadır.`, bilinmiyor: false, detay: d.t };
  if (d.b === 'muaf') return { metin: 'Vize şartı bulunmamaktadır.', bilinmiyor: false, detay: d.t };
  return { metin: '', bilinmiyor: true, detay: d.t };
};
const normalizeBank = (b) => {
  b = b || {};
  // accounts dizisi yoksa eski alanlardan üret; varsa ibanTL/EUR/USD alanlarını accounts'tan doldur (belge üreticileri için)
  const accounts = Array.isArray(b.accounts) && b.accounts.length ? b.accounts.filter(a => a.iban) : [
    ...(b.ibanTL ? [{ currency: 'TL', iban: b.ibanTL, accountNo: b.accountTL || '' }] : []),
    ...(b.ibanEUR ? [{ currency: 'EUR', iban: b.ibanEUR, accountNo: b.accountEUR || '' }] : []),
    ...(b.ibanUSD ? [{ currency: 'USD', iban: b.ibanUSD, accountNo: '' }] : []),
  ];
  const byC = (c) => accounts.find(a => a.currency === c);
  return { ...b, accounts,
    bankName: b.bankName || '', branch: b.branch || '', branchCode: b.branchCode || '', swift: b.swift || '',
    ibanTL: byC('TL')?.iban || b.ibanTL || '', accountTL: byC('TL')?.accountNo || b.accountTL || '',
    ibanEUR: byC('EUR')?.iban || b.ibanEUR || '', accountEUR: byC('EUR')?.accountNo || b.accountEUR || '',
    ibanUSD: byC('USD')?.iban || b.ibanUSD || '' };
};
const getActiveBanks = (settings) => {
  const hasData = (b) => b.bankName || b.ibanTL || b.ibanEUR || (Array.isArray(b.accounts) && b.accounts.some(a => a.iban));
  const banks = Array.isArray(settings?.banks) ? settings.banks.filter(hasData) : [];
  // Önce "belgelerde göster" işaretliler; hiç işaretli yoksa ilk dolu bankayı kullan
  const flagged = banks.filter(b => b.showInDocs);
  const use = flagged.length ? flagged : banks;
  if (use.length) return use.map(normalizeBank);
  return [normalizeBank(DEFAULT_BANK)];
};
