// İŞLEM LOGU — önemli işlemleri activity_logs koleksiyonuna yazar.
// user: currentUser objesi (name içerir). Sessiz çalışır, hata olsa akışı bozmaz.
const logActivity = async (action, modul, detay, user, extra = {}) => {
  try {
    const id = generateUniqueId();
    await setDoc(doc(db, 'activity_logs', id), {
      id,
      action,                                   // 'create' | 'delete' | 'status'
      modul,                                    // 'Müşteri' | 'Vize' | 'Tur' | 'Pasaport' ...
      detay: detay || '',                       // "Ahmet Yılmaz" gibi
      userName: user?.name || user?.email || 'Bilinmiyor',
      userEmail: user?.email || '',
      time: new Date().toISOString(),
      ...extra
    });
  } catch (e) { /* log yazımı akışı bozmaz */ }
};

// Telefon formatla: +90 5XX XXX XX XX
const formatPhoneNumber = (value) => {
  let cleaned = value.replace(/\D/g, '');
  // 90 ile başlıyorsa kaldır
  if (cleaned.startsWith('90')) cleaned = cleaned.slice(2);
  // 0 ile başlıyorsa kaldır
  if (cleaned.startsWith('0')) cleaned = cleaned.slice(1);
  // Max 10 hane
  cleaned = cleaned.slice(0, 10);
  // Format: XXX XXX XX XX
  let formatted = '';
  if (cleaned.length > 0) formatted += cleaned.slice(0, 3);
  if (cleaned.length > 3) formatted += ' ' + cleaned.slice(3, 6);
  if (cleaned.length > 6) formatted += ' ' + cleaned.slice(6, 8);
  if (cleaned.length > 8) formatted += ' ' + cleaned.slice(8, 10);
  return formatted ? '+90 ' + formatted : '+90 5';
};

// Pasaport No formatla: İlk harf büyük, 9 karakter
const formatPassportNo = (value) => {
  const cleaned = value.toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!cleaned) return '';
  const letter = cleaned[0].match(/[A-Z]/) ? cleaned[0] : '';
  if (!letter) return cleaned.slice(0, 1); // harf girilene kadar bekle
  const digits = cleaned.slice(1).replace(/[^0-9]/g, '').slice(0, 7);
  return letter + digits;
};

// Türkçe + büyük/küçük harf duyarsız normalize (arama için): Önder=Onder=ÖNDER
// Tarih alanı "gg.aa.yyyy" native input'unda yıl anormal (1900 öncesi / 2100 sonrası) girilirse yakalar
const isSaneDate = (iso) => {
  if (!iso) return true; // boş tarih ayrı yerde zorunlu kontrolü yapılıyor
  const m = String(iso).match(/^(\d{4})-\d{2}-\d{2}$/);
  if (!m) return false;
  const y = parseInt(m[1], 10);
  return y >= 1900 && y <= 2100;
};
const normalizeTr = (s) => (s == null ? '' : String(s))
  .replace(/[İIı]/g, 'i').replace(/[Ğğ]/g, 'g').replace(/[Üü]/g, 'u')
  .replace(/[Şş]/g, 's').replace(/[Öö]/g, 'o').replace(/[Çç]/g, 'c')
  .toLowerCase().trim();

// Vize başvurusu bu müşteriye mi ait? customerId (id/_docId) önce; ID yoksa ya da hiçbir müşteriye denk gelmiyorsa ad-soyad ile eşleştir
const visaAppBelongsTo = (v, c, customers) => {
  if (!v || !c) return false;
  const vid = v.customerId != null && v.customerId !== '' ? String(v.customerId) : '';
  if (vid && (vid === String(c.id) || (c._docId && vid === String(c._docId)))) return true;
  const nm = (s) => normalizeTr(s).replace(/\s+/g, ' ');
  const full = nm(`${c.firstName || ''} ${c.lastName || ''}`);
  if (!full) return false;
  // Başka bir müşteriye bağlıysa: o müşteri aynı isimde (mükerrer kayıt, ör. Aktekin/Aktekın) ise yine göster
  const linked = vid ? (customers || []).find(x => vid === String(x.id) || (x._docId && vid === String(x._docId))) : null;
  if (linked) return nm(`${linked.firstName || ''} ${linked.lastName || ''}`) === full;
  return nm(v.customerName || '') === full;
};

// TC Kimlik No algoritma kontrolü (11 hane, 0 ile başlamaz, 10. ve 11. hane kontrol basamakları)
const isValidTc = (tc) => {
  const t = String(tc || '').trim();
  if (!/^[1-9]\d{10}$/.test(t)) return false;
  const d = t.split('').map(Number);
  const d10 = ((d[0] + d[2] + d[4] + d[6] + d[8]) * 7 - (d[1] + d[3] + d[5] + d[7])) % 10;
  return ((d10 + 10) % 10) === d[9] && d.slice(0, 10).reduce((a, b) => a + b, 0) % 10 === d[10];
};
const sameCustName = (a, b) => {
  const nm = (x) => normalizeTr(`${x?.firstName || ''} ${x?.lastName || ''}`).replace(/\s+/g, ' ');
  return nm(a) === nm(b);
};
// Olası mükerrer müşteriler: aynı TC, aynı pasaport no, ya da aynı ad-soyad + doğum tarihi (OCR TC/pasaport no'yu yanlış okusa bile yakalar)
const findLikelyDuplicates = (c, customers) => {
  if (!c) return [];
  const nm = (s) => normalizeTr(s).replace(/\s+/g, ' ');
  const key = (x) => x._docId || String(x.id);
  const full = nm(`${c.firstName || ''} ${c.lastName || ''}`);
  const tc = String(c.tcKimlik || '').trim();
  const ppNos = new Set(safeParseJSON(c.passports || c._passports).map(p => String(p.passportNo || '').trim().toUpperCase()).filter(Boolean));
  return (customers || []).filter(x => {
    if (c.id != null && (key(x) === key(c) || String(x.id) === String(c.id))) return false;
    if (tc.length === 11 && String(x.tcKimlik || '').trim() === tc) return true;
    if (ppNos.size && safeParseJSON(x.passports).some(p => ppNos.has(String(p.passportNo || '').trim().toUpperCase()))) return true;
    return !!full && !!c.birthDate && x.birthDate === c.birthDate && nm(`${x.firstName || ''} ${x.lastName || ''}`) === full;
  });
};

// Sadece görüntüleme için: "ONDER TASCI" / "önder taşçı" -> "Önder Taşçı" (Türkçe imla, i/İ ayrımına dikkat eder)
const titleCaseTr = (s) => {
  if (!s) return '';
  const lower = String(s).replace(/İ/g, 'i').replace(/I/g, 'ı').toLowerCase();
  return lower.replace(/(^|[\s\-'])(\p{L})/gu, (m, sep, ch) => sep + (ch === 'i' ? 'İ' : ch.toLocaleUpperCase('tr-TR')));
};

// Yer adı (doğum yeri / il): pasaporttaki büyük harfli ASCII yazımı ("DENIZLI", "Denızli") il listesiyle eşleştirip doğru yazar.
const PLACE_ALIAS = { afyon: 'Afyonkarahisar', maras: 'Kahramanmaraş', 'k.maras': 'Kahramanmaraş', urfa: 'Şanlıurfa', antep: 'Gaziantep', icel: 'Mersin', izmit: 'Kocaeli', adapazari: 'Sakarya', antakya: 'Hatay' };
const placeTr = (s) => {
  if (!s) return '';
  const n = normalizeTr(s);
  const hit = turkishProvinces.find(p => normalizeTr(p) === n) || PLACE_ALIAS[n];
  return hit || titleCaseTr(s);
};

const validatePassportNo = (passportNo) => {
  if (!passportNo) return null;
  const regex = /^[A-Z][0-9]{7,8}$/;
  if (!regex.test(passportNo)) return '❌ Pasaport no 1 harf + 7-8 rakam olmalı (örn: U1234567)';
  return null; // geçerli
};

// Pasaport No'dan türü otomatik tespit
const detectPassportType = (passportNo) => {
  if (!passportNo) return null;
  const first = passportNo.toUpperCase()[0];
  if (first === 'U') return 'Bordo Pasaport (Umuma Mahsus)';
  if (first === 'S') return 'Yeşil Pasaport (Hususi)';
  if (first === 'Z') return 'Gri Pasaport (Hizmet)';
  if (first === 'D') return 'Siyah Pasaport (Diplomatik)';
  return null;
};

const countryCodeMap = { TUR:'Türkiye',DEU:'Almanya',FRA:'Fransa',GBR:'İngiltere',USA:'Amerika Birleşik Devletleri',NLD:'Hollanda',BEL:'Belçika',AUT:'Avusturya',CHE:'İsviçre',ITA:'İtalya',ESP:'İspanya',PRT:'Portekiz',GRC:'Yunanistan',SWE:'İsveç',NOR:'Norveç',DNK:'Danimarka',FIN:'Finlandiya',POL:'Polonya',CZE:'Çekya',HUN:'Macaristan',ROU:'Romanya',BGR:'Bulgaristan',HRV:'Hırvatistan',RUS:'Rusya',UKR:'Ukrayna',AZE:'Azerbaycan',KAZ:'Kazakistan',SAU:'Suudi Arabistan',ARE:'Birleşik Arap Emirlikleri',IRN:'İran',IRQ:'Irak',SYR:'Suriye',JOR:'Ürdün',LBN:'Lübnan',EGY:'Mısır',MAR:'Fas',TUN:'Tunus',ALB:'Arnavutluk',MKD:'Kuzey Makedonya',SRB:'Sırbistan',BIH:'Bosna Hersek',MNE:'Karadağ',GEO:'Gürcistan',ARM:'Ermenistan',CHN:'Çin',JPN:'Japonya',KOR:'Güney Kore',IND:'Hindistan',PAK:'Pakistan',BGD:'Bangladeş',IDN:'Endonezya',MYS:'Malezya',THA:'Tayland',VNM:'Vietnam',PHL:'Filipinler',BRA:'Brezilya',ARG:'Arjantin',MEX:'Meksika',CAN:'Kanada',AUS:'Avustralya',NZL:'Yeni Zelanda',ZAF:'Güney Afrika',NGA:'Nijerya',ETH:'Etiyopya',KEN:'Kenya' };
const isoToCountry = (code) => code ? (countryCodeMap[code.toUpperCase()] || code) : '';

// Toast Component
function Toast({ toasts, removeToast }) {
  return (
    // Sağ altta dikdörtgen kutular — üstteki butonları (➕ Rezervasyon vb.) ve formların alt Kaydet çubuğunu kapatmasın
    <div style={{ position: 'fixed', bottom: '110px', right: '20px', zIndex: 9999, display: 'flex', flexDirection: 'column-reverse', gap: '10px', maxWidth: 'calc(100vw - 40px)' }}>
      {toasts.map(toast => (
        <div key={toast.id} onClick={() => removeToast(toast.id)} style={{
          padding: '14px 18px',
          borderRadius: '6px',
          borderLeft: '5px solid rgba(255,255,255,0.55)',
          background: toast.type === 'success' ? 'linear-gradient(135deg, #10b981, #059669)' : 
                      toast.type === 'error' ? 'linear-gradient(135deg, #ef4444, #dc2626)' : 
                      toast.type === 'warning' ? 'linear-gradient(135deg, #f59e0b, #d97706)' : 
                      'linear-gradient(135deg, #3b82f6, #2563eb)',
          color: 'white',
          boxShadow: '0 10px 40px rgba(0,0,0,0.3)',
          cursor: 'pointer',
          display: 'flex',
          alignItems: 'center',
          gap: '10px',
          width: '340px',
          maxWidth: '100%',
          boxSizing: 'border-box',
          animation: 'slideIn 0.3s ease',
          fontSize: '14px',
          fontWeight: '500'
        }}>
          <span style={{ fontSize: '18px' }}>
            {toast.type === 'success' ? '✅' : toast.type === 'error' ? '❌' : toast.type === 'warning' ? '⚠️' : 'ℹ️'}
          </span>
          <span style={{ flex: 1 }}>{toast.message}</span>
          {toast.undo && (
            <button onClick={(e) => { e.stopPropagation(); toast.undo(); removeToast(toast.id); }} style={{
              background: 'rgba(255,255,255,0.2)',
              border: 'none',
              borderRadius: '6px',
              padding: '6px 12px',
              color: 'white',
              cursor: 'pointer',
              fontSize: '12px',
              fontWeight: '600'
            }}>↩️ Geri Al</button>
          )}
        </div>
      ))}
      <style>{`@keyframes slideIn { from { transform: translateX(100%); opacity: 0; } to { transform: translateX(0); opacity: 1; } }`}</style>
    </div>
  );
}

// Loading Button Component
function LoadingButton({ onClick, loading, disabled, children, style, ...props }) {
  return (
    <button 
      onClick={onClick} 
      disabled={loading || disabled}
      style={{
        ...style,
        opacity: (loading || disabled) ? 0.6 : 1,
        cursor: (loading || disabled) ? 'not-allowed' : 'pointer',
        position: 'relative'
      }}
      {...props}
    >
      {loading ? (
        <span style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}>
          <span style={{ 
            width: '16px', 
            height: '16px', 
            border: '2px solid rgba(255,255,255,0.3)', 
            borderTop: '2px solid white', 
            borderRadius: '50%', 
            animation: 'spin 0.8s linear infinite' 
          }} />
          İşleniyor...
        </span>
      ) : children}
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </button>
  );
}

// Form Error Component

function CalendarPicker({ label, value, onChange, minYear = 1920, maxYear = 2035, maxDate = null, minDate = null }) {
  const [isOpen, setIsOpen] = useState(false);
  const [viewDate, setViewDate] = useState(() => {
    if (value) {
      const parts = value.split('-');
      return { year: parseInt(parts[0]), month: parseInt(parts[1]) - 1 };
    }
    return { year: new Date().getFullYear(), month: new Date().getMonth() };
  });
  
  const months = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık'];
  const days = ['Pt', 'Sa', 'Ça', 'Pe', 'Cu', 'Ct', 'Pz'];
  
  const getDaysInMonth = (year, month) => new Date(year, month + 1, 0).getDate();
  const getFirstDayOfMonth = (year, month) => {
    const day = new Date(year, month, 1).getDay();
    return day === 0 ? 6 : day - 1;
  };
  
  const formatDisplay = (val) => {
    if (!val) return '';
    const parts = val.split('-');
    if (parts.length !== 3) return val;
    return `${parts[2]}.${parts[1]}.${parts[0]}`;
  };
  
  const handleSelect = (day) => {
    const dateStr = `${viewDate.year}-${String(viewDate.month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    onChange(dateStr);
    setIsOpen(false);
  };
  
  const prevMonth = () => {
    setViewDate(prev => {
      if (prev.month === 0) return { year: prev.year - 1, month: 11 };
      return { ...prev, month: prev.month - 1 };
    });
  };
  
  const nextMonth = () => {
    setViewDate(prev => {
      if (prev.month === 11) return { year: prev.year + 1, month: 0 };
      return { ...prev, month: prev.month + 1 };
    });
  };
  
  const isDateDisabled = (day) => {
    const date = new Date(viewDate.year, viewDate.month, day);
    if (maxDate && date > new Date(maxDate)) return true;
    if (minDate && date < new Date(minDate)) return true;
    return false;
  };
  
  const isToday = (day) => {
    const today = new Date();
    return viewDate.year === today.getFullYear() && viewDate.month === today.getMonth() && day === today.getDate();
  };
  
  const isSelected = (day) => {
    if (!value) return false;
    const parts = value.split('-');
    return parseInt(parts[0]) === viewDate.year && parseInt(parts[1]) - 1 === viewDate.month && parseInt(parts[2]) === day;
  };
  
  const years = Array.from({ length: maxYear - minYear + 1 }, (_, i) => minYear + i);
  const daysInMonth = getDaysInMonth(viewDate.year, viewDate.month);
  const firstDay = getFirstDayOfMonth(viewDate.year, viewDate.month);
  const calendarDays = Array.from({ length: 42 }, (_, i) => {
    const day = i - firstDay + 1;
    return day > 0 && day <= daysInMonth ? day : null;
  });

  return (
    <div style={{ position: 'relative' }}>
      <label style={labelStyle}>{label}</label>
      <div 
        onClick={() => setIsOpen(!isOpen)}
        style={{ ...inputStyle, cursor: 'pointer', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}
      >
        <span style={{ color: value ? '#e8f1f8' : '#64748b' }}>{formatDisplay(value) || 'Tarih seçin'}</span>
        <span style={{ fontSize: '14px' }}>📅</span>
      </div>
      
      {isOpen && (
        <>
          <div onClick={() => setIsOpen(false)} style={{ position: 'fixed', inset: 0, zIndex: 400 }} />
          <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, marginTop: '4px', background: '#0f2744', border: '1px solid rgba(255,255,255,0.2)', borderRadius: '12px', padding: '12px', zIndex: 401, boxShadow: '0 10px 40px rgba(0,0,0,0.5)', minWidth: '280px' }}>
            {/* Header - Month/Year Select */}
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '12px' }}>
              <button type="button" onClick={prevMonth} style={{ background: 'rgba(255,255,255,0.1)', border: 'none', borderRadius: '6px', width: '32px', height: '32px', color: '#e8f1f8', cursor: 'pointer', fontSize: '16px' }}>‹</button>
              <div style={{ display: 'flex', gap: '8px' }}>
                <select 
                  value={viewDate.month} 
                  onChange={e => setViewDate({ ...viewDate, month: parseInt(e.target.value) })}
                  style={{ background: 'rgba(255,255,255,0.1)', border: 'none', borderRadius: '6px', padding: '6px 8px', color: '#e8f1f8', fontSize: '13px', cursor: 'pointer' }}
                >
                  {months.map((m, i) => <option key={i} value={i} style={{ background: '#0f2744' }}>{m}</option>)}
                </select>
                <select 
                  value={viewDate.year} 
                  onChange={e => setViewDate({ ...viewDate, year: parseInt(e.target.value) })}
                  style={{ background: 'rgba(255,255,255,0.1)', border: 'none', borderRadius: '6px', padding: '6px 8px', color: '#e8f1f8', fontSize: '13px', cursor: 'pointer' }}
                >
                  {years.map(y => <option key={y} value={y} style={{ background: '#0f2744' }}>{y}</option>)}
                </select>
              </div>
              <button type="button" onClick={nextMonth} style={{ background: 'rgba(255,255,255,0.1)', border: 'none', borderRadius: '6px', width: '32px', height: '32px', color: '#e8f1f8', cursor: 'pointer', fontSize: '16px' }}>›</button>
            </div>
            
            {/* Day Headers */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '2px', marginBottom: '4px' }}>
              {days.map(d => (
                <div key={d} style={{ textAlign: 'center', fontSize: '11px', color: '#64748b', padding: '4px', fontWeight: '600' }}>{d}</div>
              ))}
            </div>
            
            {/* Calendar Grid */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '2px' }}>
              {calendarDays.map((day, i) => (
                <div key={i}>
                  {day && (
                    <button
                      type="button"
                      onClick={() => !isDateDisabled(day) && handleSelect(day)}
                      disabled={isDateDisabled(day)}
                      style={{
                        width: '100%',
                        aspectRatio: '1',
                        border: 'none',
                        borderRadius: '8px',
                        background: isSelected(day) ? 'linear-gradient(135deg, #f59e0b, #d97706)' : isToday(day) ? 'rgba(59,130,246,0.3)' : 'transparent',
                        color: isSelected(day) ? '#0c1929' : isDateDisabled(day) ? '#4a5568' : '#e8f1f8',
                        cursor: isDateDisabled(day) ? 'not-allowed' : 'pointer',
                        fontSize: '13px',
                        fontWeight: isSelected(day) || isToday(day) ? '600' : '400',
                        transition: 'all 0.15s'
                      }}
                    >
                      {day}
                    </button>
                  )}
                </div>
              ))}
            </div>
            
            {/* Quick Actions */}
            <div style={{ display: 'flex', gap: '8px', marginTop: '12px', paddingTop: '12px', borderTop: '1px solid rgba(255,255,255,0.1)' }}>
              <button 
                type="button"
                onClick={() => { const t = new Date(); handleSelect(t.getDate()); setViewDate({ year: t.getFullYear(), month: t.getMonth() }); }}
                style={{ flex: 1, padding: '8px', background: 'rgba(59,130,246,0.2)', border: 'none', borderRadius: '6px', color: '#3b82f6', fontSize: '11px', cursor: 'pointer' }}
              >
                Bugün
              </button>
              <button 
                type="button"
                onClick={() => { onChange(''); setIsOpen(false); }}
                style={{ flex: 1, padding: '8px', background: 'rgba(239,68,68,0.2)', border: 'none', borderRadius: '6px', color: '#ef4444', fontSize: '11px', cursor: 'pointer' }}
              >
                Temizle
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

function BirthDateInput({ label, value, onChange }) {
  return <CalendarPicker label={label} value={value} onChange={onChange} minYear={1920} maxYear={new Date().getFullYear()} maxDate={new Date().toISOString().split('T')[0]} />;
}

function DateInput({ label, value, onChange }) {
  return <CalendarPicker label={label} value={value} onChange={onChange} minYear={2020} maxYear={2040} />;
}

function FormInput({ label, ...p }) { return (<div><label style={labelStyle}>{label}</label><input {...p} style={inputStyle} /></div>); }
function StatCard({ value, label, color, onClick, sublabel }) { return (<div onClick={onClick} style={{ background: `${color}15`, border: `1px solid ${color}30`, borderRadius: '12px', padding: '16px', cursor: onClick ? 'pointer' : 'default', minHeight: '80px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}><div style={{ fontSize: '28px', fontWeight: '700', color }}>{value}</div><div style={{ fontSize: '12px', color: '#94a3b8', marginTop: '4px' }}>{label}</div>{sublabel && <div style={{ fontSize: '10px', color, marginTop: '4px' }}>{sublabel}</div>}</div>); }
function Modal({ children, onClose, title }) { return (<div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.85)', backdropFilter: 'blur(5px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 300, padding: '20px' }}><div style={{ background: 'linear-gradient(180deg, #0f2744 0%, #0c1929 100%)', borderRadius: '12px', width: '100%', maxWidth: '400px', maxHeight: '85vh', overflow: 'auto', border: '1px solid rgba(255,255,255,0.1)' }}><div style={{ padding: '14px 16px', borderBottom: '1px solid rgba(255,255,255,0.1)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}><h3 style={{ margin: 0, fontSize: '15px', flex: 1 }}>{title}</h3><button onClick={onClose} style={{ background: 'rgba(255,255,255,0.1)', border: 'none', borderRadius: '6px', width: '28px', height: '28px', cursor: 'pointer', color: '#94a3b8', fontSize: '14px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>✕</button></div><div style={{ padding: '14px 16px' }}>{children}</div></div></div>); }
function InfoBox({ label, value, highlight }) { return (<div style={{ background: highlight ? 'rgba(245,158,11,0.1)' : 'rgba(255,255,255,0.03)', borderRadius: '6px', padding: '8px', border: highlight ? '1px solid rgba(245,158,11,0.2)' : 'none' }}><p style={{ fontSize: '10px', color: highlight ? '#f59e0b' : '#64748b', marginBottom: '2px', textTransform: 'uppercase' }}>{label}</p><p style={{ fontSize: '12px', margin: 0, color: value ? (highlight ? '#f59e0b' : '#e8f1f8') : '#64748b' }}>{value || '-'}</p></div>); }

function LoginScreen({ onLogin, users }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = async (e) => {
    e.preventDefault();
    setError('');
    if (!email) { setError('E-posta adresi gerekli'); return; }
    if (!password) { setError('Şifre gerekli'); return; }
    setLoading(true);
    try {
      // Firebase Auth ile giriş (Firestore Rules güvenliği için)
      const cred = await signInWithEmailAndPassword(auth, email.trim(), password);
      // users koleksiyonundan profil/rol bul — giriş ekranındaki liste sadece yerel önbellek
      // (yeni cihazda boş); bu yüzden girişten sonra Firestore'dan okunur. Yoksa temel profil.
      const mail = email.trim().toLowerCase();
      let profile = null;
      try {
        const snap = await getDocs(collection(db, 'users'));
        const d = snap.docs.find(x => (x.data().email || '').toLowerCase() === mail);
        if (d) profile = { ...d.data(), _docId: d.id };
      } catch (e) { console.warn('Kullanıcı profili okunamadı:', e.message); }
      if (!profile) profile = users.find(u => (u.email || '').toLowerCase() === mail) || null;
      if (profile) { const { password: _pw, ...clean } = profile; profile = clean; }
      onLogin(profile || { id: cred.user.uid, email: cred.user.email, name: cred.user.email, role: 'user' });
    } catch (err) {
      if (err.code === 'auth/invalid-credential' || err.code === 'auth/wrong-password' || err.code === 'auth/user-not-found') {
        setError('E-posta veya şifre hatalı');
      } else if (err.code === 'auth/too-many-requests') {
        setError('Çok fazla deneme. Biraz bekleyin.');
      } else {
        setError('Giriş hatası: ' + (err.code || err.message));
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ position: 'fixed', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'linear-gradient(135deg, #0c1929 0%, #1a3a5c 50%, #0d2137 100%)', fontFamily: "'Segoe UI', sans-serif", padding: '20px' }}>
      <div style={{ background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '16px', padding: '40px', width: '100%', maxWidth: '380px' }}>
        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <img src="/icons/logo.png" alt="Paydos" style={{ width: '88px', height: '88px', borderRadius: '50%', display: 'block', margin: '0 auto 12px' }} />
          <h1 style={{ margin: 0, fontSize: '24px', color: '#e8f1f8', fontWeight: '700' }}>Paydos Turizm</h1>
          <p style={{ margin: '8px 0 0', fontSize: '13px', color: '#94a3b8' }}>Giriş yapın</p>
        </div>
        <form onSubmit={handleLogin}>
          <div style={{ marginBottom: '16px' }}><label style={labelStyle}>E-posta Adresi</label><input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="ornek@paydos.com" style={{ ...inputStyle, padding: '12px 14px', fontSize: '15px' }} /></div>
          <div style={{ marginBottom: '20px' }}><label style={labelStyle}>Şifre</label><input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••" style={{ ...inputStyle, padding: '12px 14px', fontSize: '15px' }} /></div>
          {error && <div style={{ background: 'rgba(239,68,68,0.15)', border: '1px solid rgba(239,68,68,0.3)', borderRadius: '8px', padding: '10px', marginBottom: '16px', fontSize: '12px', color: '#ef4444', textAlign: 'center' }}>{error}</div>}
          <button type="submit" disabled={loading} style={{ width: '100%', padding: '14px', background: loading ? 'rgba(245,158,11,0.5)' : 'linear-gradient(135deg, #f59e0b, #d97706)', border: 'none', borderRadius: '10px', color: '#0c1929', fontWeight: '700', fontSize: '15px', cursor: loading ? 'not-allowed' : 'pointer' }}>{loading ? 'Giriş yapılıyor...' : '🔓 Giriş Yap'}</button>
        </form>
      </div>
    </div>
  );
}

function DashboardModule({ customers, setCustomers, appSettings, showToast, isMobile, onNavigate, onGo }) {
  const [inboxFiles, setInboxFiles] = useState(null); // 📤 sürükle-bırak ile gelen dosyalar → Belge Yükle penceresi
  const [dragOn, setDragOn] = useState(false);
  const [showBirthdays, setShowBirthdays] = useState(false);
  const [modal, setModal] = useState(null); // {title, color, list, renderItem}
  // Bugün eklenen müşteriler
  const todayStr = new Date().toISOString().split('T')[0];
  const todayAdded = customers.filter(c => c.createdAt && String(c.createdAt).startsWith(todayStr));
  // Schengen vizesi olanlar
  // Schengen vizesi olanlar
  const withSchengen = customers.filter(c => {
    const visas = safeParseJSON(c.schengenVisas);
    return visas.some(v => v.country && v.endDate);
  });
  // USA vizesi olanlar
  const withUsa = customers.filter(c => {
    const visa = safeParseObj(c.usaVisa);
    return visa.endDate;
  });
  // Pasaportu 6 ay içinde bitecekler
  const expiringPassports = customers.filter(c => {
    const pList = safeParseJSON(c.passports);
    return pList.some(p => {
      const days = getDaysLeft(p.expiryDate);
      return days !== null && days > 0 && days <= 180;
    });
  });
  // Yeşil Pasaportlu Olanlar (passportType veya pasaport no S ile başlıyor)
  const withGreenPassport = customers.filter(c => {
    const pList = safeParseJSON(c.passports);
    return pList.some(p =>
      p.passportType === 'Yeşil Pasaport (Hususi)' ||
      p.passportType?.includes('Yeşil') ||
      (p.passportNo && p.passportNo.toUpperCase().startsWith('S'))
    );
  });
  // Bugün doğum günü olanlar
  const todayBirthdays = customers.filter(c => {
    if (!c.birthDate) return false;
    const today = new Date();
    const birth = safeParseDate(c.birthDate);
    if (!birth) return false;
    return birth.getDate() === today.getDate() && birth.getMonth() === today.getMonth();
  });
  // Bu hafta doğum günü olanlar
  const weekBirthdays = customers.filter(c => {
    if (!c.birthDate) return false;
    const today = new Date();
    const birth = safeParseDate(c.birthDate);
    if (!birth) return false;
    const thisYear = today.getFullYear();
    const bday = new Date(thisYear, birth.getMonth(), birth.getDate());
    const diff = (bday - today) / (1000 * 60 * 60 * 24);
    return diff > 0 && diff <= 7;
  });

  // Bugün Eklenen / Güncellenen Kayıtlar
  const todayActivities = (() => {
    const today = new Date();
    const isToday = (val) => {
      if (!val) return false;
      const d = val instanceof Date ? val : new Date(val);
      if (!d || isNaN(d.getTime())) return false;
      return d.getDate() === today.getDate() &&
             d.getMonth() === today.getMonth() &&
             d.getFullYear() === today.getFullYear();
    };
    const activities = [];
    customers.forEach(c => {
      const name = `${c.firstName || ''} ${c.lastName || ''}`.trim();
      if (!name) return;

      // Yeni müşteri (createdAt bugün)
      const isNewCustomer = isToday(c.createdAt);
      if (isNewCustomer) {
        activities.push({ icon: '👤', text: `${name} müşteri olarak eklendi`, time: c.createdAt });
      }

      // Pasaport (createdAt veya addedAt veya issueDate bugünse)
      safeParseJSON(c.passports).forEach(p => {
        const passTime = p.createdAt || p.addedAt;
        if (isToday(passTime)) {
          activities.push({ icon: '📘', text: `${name} pasaportu eklendi (${p.passportNo || '?'})`, time: passTime });
        }
      });

      // Schengen vize
      safeParseJSON(c.schengenVisas).forEach(v => {
        const vTime = v.createdAt || v.addedAt;
        if (isToday(vTime)) {
          const country = v.country ? ` (${v.country})` : '';
          activities.push({ icon: '🇪🇺', text: `${name} Schengen vizesi${country} eklendi`, time: vTime });
        }
      });

      // ABD vize
      const usaVisa = typeof c.usaVisa === 'string' ? (() => { try { return JSON.parse(c.usaVisa); } catch { return {}; } })() : (c.usaVisa || {});
      if (usaVisa && isToday(usaVisa.createdAt || usaVisa.addedAt)) {
        activities.push({ icon: '🇺🇸', text: `${name} ABD vizesi eklendi`, time: usaVisa.createdAt || usaVisa.addedAt });
      }

      // Yeni müşteri olmadığı halde bugün güncellenmiş - generic kayıt
      if (!isNewCustomer && isToday(c.updatedAt || c.lastEditedAt)) {
        // Yukarıdaki pasaport/vize aktiviteleri yoksa bu güncellemeyi göster
        const alreadyListed = activities.some(a => a.text.includes(name));
        if (!alreadyListed) {
          activities.push({ icon: '✏️', text: `${name} kaydı güncellendi`, time: c.updatedAt || c.lastEditedAt });
        }
      }
    });
    // En son üstte
    activities.sort((a, b) => new Date(b.time) - new Date(a.time));
    return activities;
  })();

  const getAge = (birthDate) => {
    const birth = safeParseDate(birthDate);
    if (!birth) return '';
    const today = new Date();
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
    return age;
  };

  return (
    <div style={{ padding: isMobile ? '16px' : '24px' }}>
      <h2 style={{ fontSize: '20px', marginBottom: '16px' }}>📊 Dashboard</h2>
      {/* ⚡ Hızlı işlemler: tıklayınca ilgili modülde yeni kayıt formu açılır */}
      {onGo && (() => {
        // Amerika vize: kişiye özel DS-160 linki doğrudan panoya
        const ds160Link = () => {
          const raw = String(appSettings?.ds160SiteUrl || 'https://ds160-paydos.netlify.app').trim();
          const url = /^https?:\/\//i.test(raw) ? raw : `https://${raw.replace(/^\/+/, '')}`;
          const link = `${url}${url.includes('?') ? '&' : '?'}id=${'a' + Math.random().toString(36).slice(2, 8) + Date.now().toString(36)}`;
          navigator.clipboard.writeText(link).then(() => showToast?.('🇺🇸 Yeni DS-160 linki kopyalandı — müşteriye gönderin', 'success'), () => window.prompt('Linki kopyalayın:', link));
        };
        const items = [
          ['visa', 'new', '🌍', 'Yeni Vize Başvurusu', '#10b981'], ['customers', 'new', '👤', 'Yeni Müşteri', '#3b82f6'], ['ds160', 'link', '🇺🇸', 'Amerika Vize Linki', '#8b5cf6'],
          ['tours', 'new', '🎫', 'Yeni Tur', '#f59e0b'], ['quotes', 'offer', '🧾', 'Yeni Tur Teklifi', '#e8912a'], ['quotes', 'new', '📄', 'Yeni Teklif / Proforma', '#ef4444'],
          ['quotes', 'contract', '📜', 'Yeni Sözleşme', '#6366f1'], ['tavsiyeler', null, '⭐', 'Tavsiye Ekle', '#fb923c'],
        ];
        return (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', marginBottom: '20px' }}>
            {items.map(([id, act, icon, label, color]) => (
              <button key={id + act} onClick={() => act === 'link' ? ds160Link() : onGo(id, act)} title={act === 'link' ? 'Müşteriye özel yeni DS-160 linki kopyalar' : label}
                style={{ display: 'inline-flex', alignItems: 'center', gap: '7px', padding: isMobile ? '8px 12px' : '9px 14px', background: `${color}1a`, border: `1px solid ${color}55`, borderRadius: '999px', color: '#e8f1f8', cursor: 'pointer', fontSize: isMobile ? '12px' : '13px', fontWeight: 600, whiteSpace: 'nowrap', transition: 'background .12s, border-color .12s' }}
                onMouseEnter={e => { e.currentTarget.style.background = `${color}33`; e.currentTarget.style.borderColor = color; }}
                onMouseLeave={e => { e.currentTarget.style.background = `${color}1a`; e.currentTarget.style.borderColor = `${color}55`; }}>
                <span style={{ fontSize: '15px', lineHeight: 1 }}>{icon}</span>{label}
              </button>
            ))}
          </div>
        );
      })()}
      {inboxFiles && <BulkDocInbox customers={customers} setCustomers={setCustomers} appSettings={appSettings} showToast={showToast} initialFiles={inboxFiles} onClose={() => setInboxFiles(null)} />}
      <div style={{ display: 'grid', gridTemplateColumns: isMobile ? 'repeat(2, 1fr)' : 'repeat(3, 1fr)', gap: '12px', marginBottom: '24px' }}>
        <StatCard value={customers.length} label="Toplam Müşteri" color="#3b82f6"
          sublabel={todayAdded.length > 0 ? `+${todayAdded.length} bugün eklendi` : null} />
        <StatCard value={withSchengen.length} label="Schengen Vizeli" color="#10b981"
          sublabel="→ Listele"
          onClick={() => setModal({ title: '🇪🇺 Schengen Vizeli', color: '#10b981', list: withSchengen,
            renderItem: c => `${c.firstName} ${c.lastName}` })} />
        <StatCard value={withUsa.length} label="ABD Vizeli" color="#8b5cf6"
          sublabel="→ Listele"
          onClick={() => setModal({ title: '🇺🇸 ABD Vizeli', color: '#8b5cf6', list: withUsa,
            renderItem: c => `${c.firstName} ${c.lastName}` })} />
        <StatCard value={expiringPassports.length} label="Pasaport Uyarı" color="#ef4444"
          sublabel="→ 6 ay içinde bitenler"
          onClick={() => setModal({ title: '⚠️ Pasaport Uyarısı (6 ay)', color: '#ef4444', list: expiringPassports,
            renderItem: c => { const p = safeParseJSON(c.passports).find(x=>{const d=getDaysLeft(x.expiryDate);return d!==null&&d>0&&d<=180;}); return `${c.firstName} ${c.lastName} (${getDaysLeft(p?.expiryDate)} gün)`; } })} />
        <StatCard value={withGreenPassport.length} label="Yeşil Pasaport" color="#059669"
          sublabel="→ Listele"
          onClick={() => setModal({ title: '🟢 Yeşil Pasaport', color: '#059669', list: withGreenPassport,
            renderItem: c => `${c.firstName} ${c.lastName}` })} />
        <div onClick={() => setShowBirthdays(true)} style={{ background: 'rgba(245,158,11,0.1)', border: '1px solid rgba(245,158,11,0.3)', borderRadius: '12px', padding: '16px', cursor: 'pointer', minHeight: '80px', display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
          <div style={{ fontSize: '28px', fontWeight: '700', color: '#f59e0b' }}>🎂 {todayBirthdays.length}</div>
          <div style={{ fontSize: '12px', color: '#94a3b8', marginTop: '4px' }}>Bugün Doğanlar</div>
          <div style={{ fontSize: '10px', color: '#f59e0b', marginTop: '4px' }}>🎉 Tıkla ve gör!</div>
        </div>
      </div>
      {/* 📤 Belge yükle: bilet / biniş kartı / otel / vize PDF'lerini sürükle-bırak; isimden müşteri bulunur, müşteri linkine eklenir */}
      <label
        onDragEnter={e => { e.preventDefault(); setDragOn(true); }}
        onDragOver={e => { e.preventDefault(); if (!dragOn) setDragOn(true); }}
        onDragLeave={e => { if (!e.currentTarget.contains(e.relatedTarget)) setDragOn(false); }}
        onDrop={e => { e.preventDefault(); setDragOn(false); const f = Array.from(e.dataTransfer.files || []); if (f.length) setInboxFiles(f); }}
        style={{ display: 'flex', alignItems: 'center', gap: '22px', padding: isMobile ? '28px 18px' : '44px 36px', minHeight: isMobile ? '150px' : '190px', marginBottom: '24px', borderRadius: '16px', cursor: 'pointer',
          border: `2px dashed ${dragOn ? '#60a5fa' : 'rgba(59,130,246,0.4)'}`, background: dragOn ? 'rgba(59,130,246,0.16)' : 'rgba(59,130,246,0.06)', transition: 'background .15s, border-color .15s' }}>
        <div style={{ fontSize: isMobile ? '48px' : '64px' }}>{dragOn ? '📥' : '📤'}</div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: isMobile ? '18px' : '22px', fontWeight: 700, color: '#60a5fa' }}>{dragOn ? 'Bırakın, belgeler okunsun' : 'Belge yükle — sürükleyip bırakın'}</div>
          <div style={{ fontSize: isMobile ? '13px' : '14px', color: '#94a3b8', marginTop: '6px', lineHeight: 1.5 }}>Uçak bileti, biniş kartı, otel, vize… PDF'teki isimden müşteri bulunur ve müşteri linkine eklenir. Toplu bilet PDF'i kişilere ayrılır.</div>
        </div>
        {!isMobile && <span style={{ padding: '13px 24px', borderRadius: '12px', background: 'linear-gradient(135deg, #3b82f6, #2563eb)', color: '#fff', fontWeight: 700, fontSize: '15px', whiteSpace: 'nowrap' }}>Dosya seç</span>}
        <input type="file" multiple accept="application/pdf,image/*" style={{ display: 'none' }} onChange={e => { const f = Array.from(e.target.files || []); e.target.value = ''; if (f.length) setInboxFiles(f); }} />
      </label>

      {/* Generic Liste Modal */}
      {modal && (
        <div onClick={() => setModal(null)} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '20px' }}>
          <div onClick={e => e.stopPropagation()} style={{ background: 'linear-gradient(135deg, #0f2744, #1a3a5c)', borderRadius: '16px', border: `1px solid ${modal.color}30`, padding: '24px', width: '100%', maxWidth: '520px', maxHeight: '80vh', display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
              <h3 style={{ margin: 0, fontSize: '16px', color: modal.color }}>{modal.title} ({modal.list.length})</h3>
              <button onClick={() => setModal(null)} style={{ background: 'rgba(255,255,255,0.1)', border: 'none', borderRadius: '8px', color: '#94a3b8', cursor: 'pointer', padding: '6px 12px', fontSize: '14px' }}>✕</button>
            </div>
            <div style={{ overflowY: 'auto', flex: 1 }}>
              {modal.list.length === 0 ? (
                <p style={{ color: '#64748b', textAlign: 'center', padding: '20px' }}>Kayıt yok</p>
              ) : modal.list.map((c, i) => (
                <div key={c.id || i}
                  onClick={() => { setModal(null); onNavigate?.(c); }}
                  style={{ padding: '10px 12px', background: 'rgba(255,255,255,0.03)', borderRadius: '8px', marginBottom: '6px', fontSize: '13px', color: '#e8f1f8', borderLeft: `3px solid ${modal.color}40`, cursor: 'pointer', transition: 'background 0.15s' }}
                  onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.08)'}
                  onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.03)'}
                >
                  <span style={{ marginRight: '8px', fontSize: '11px', color: '#64748b' }}>→</span>
                  {modal.renderItem(c)}
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Doğum Günü Modal */}
      {showBirthdays && (
        <div onClick={(e) => { if (e.target === e.currentTarget) setShowBirthdays(false); }} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
          <div style={{ background: 'linear-gradient(135deg, #0f2744, #1a3a5c)', borderRadius: '16px', border: '1px solid rgba(255,255,255,0.15)', padding: '24px', width: isMobile ? '95%' : '500px', maxHeight: '80vh', overflowY: 'auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
              <h3 style={{ margin: 0, fontSize: '18px' }}>🎂 Doğum Günleri</h3>
              <button onClick={() => setShowBirthdays(false)} style={{ background: 'rgba(239,68,68,0.2)', border: 'none', borderRadius: '8px', color: '#ef4444', cursor: 'pointer', padding: '6px 12px', fontSize: '14px' }}>✕</button>
            </div>

            {/* Bugün Doğanlar */}
            <div style={{ marginBottom: '20px' }}>
              <div style={{ fontSize: '14px', fontWeight: '600', color: '#f59e0b', marginBottom: '10px', display: 'flex', alignItems: 'center', gap: '6px' }}>🎉 Bugün ({todayBirthdays.length})</div>
              {todayBirthdays.length === 0 ? (
                <p style={{ color: '#64748b', fontSize: '13px', padding: '12px', background: 'rgba(0,0,0,0.2)', borderRadius: '8px' }}>Bugün doğum günü olan müşteri yok</p>
              ) : (
                todayBirthdays.map(c => (
                  <div key={c.id} onClick={() => { setShowBirthdays(false); onNavigate?.(c); }} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 12px', background: 'rgba(245,158,11,0.1)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: '10px', marginBottom: '6px', cursor: 'pointer' }}>
                    <div>
                      <div style={{ fontWeight: '600', fontSize: '14px' }}>🎂 {titleCaseTr(c.firstName)} {titleCaseTr(c.lastName)}</div>
                      <div style={{ fontSize: '11px', color: '#94a3b8' }}>{c.phone || '—'} · {getAge(c.birthDate)} yaşında</div>
                    </div>
                    {c.phone && (
                      <a href={`https://wa.me/${formatWhatsAppPhone(c.phone)}`} target="_blank" rel="noreferrer" style={{ background: 'rgba(37,211,102,0.2)', border: 'none', borderRadius: '8px', color: '#25d366', padding: '6px 10px', fontSize: '12px', textDecoration: 'none', cursor: 'pointer' }}>💬 Kutla</a>
                    )}
                  </div>
                ))
              )}
            </div>

            {/* Bu Hafta Doğacaklar */}
            <div>
              <div style={{ fontSize: '14px', fontWeight: '600', color: '#3b82f6', marginBottom: '10px', display: 'flex', alignItems: 'center', gap: '6px' }}>📅 Bu Hafta ({weekBirthdays.length})</div>
              {weekBirthdays.length === 0 ? (
                <p style={{ color: '#64748b', fontSize: '13px', padding: '12px', background: 'rgba(0,0,0,0.2)', borderRadius: '8px' }}>Bu hafta doğum günü olan müşteri yok</p>
              ) : (
                weekBirthdays.map(c => {
                  const birth = safeParseDate(c.birthDate);
                  const bday = birth ? `${birth.getDate()}/${birth.getMonth()+1}` : '';
                  return (
                    <div key={c.id} onClick={() => { setShowBirthdays(false); onNavigate?.(c); }} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '10px 12px', background: 'rgba(59,130,246,0.1)', border: '1px solid rgba(59,130,246,0.15)', borderRadius: '10px', marginBottom: '6px', cursor: 'pointer' }}>
                      <div>
                        <div style={{ fontWeight: '600', fontSize: '14px' }}>{titleCaseTr(c.firstName)} {titleCaseTr(c.lastName)}</div>
                        <div style={{ fontSize: '11px', color: '#94a3b8' }}>{bday} · {c.phone || '—'} · {getAge(c.birthDate)} yaşında</div>
                      </div>
                      {c.phone && (
                        <a href={`https://wa.me/${formatWhatsAppPhone(c.phone)}`} target="_blank" rel="noreferrer" style={{ background: 'rgba(37,211,102,0.15)', border: 'none', borderRadius: '8px', color: '#25d366', padding: '6px 10px', fontSize: '12px', textDecoration: 'none', cursor: 'pointer' }}>💬 WA</a>
                      )}
                    </div>
                  );
                })
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// === Firma seçici: DTO üye listesinden arar, yoksa elle eklemeye izin verir ===
let _companyCache = null;
const loadCompanies = async () => {
  if (_companyCache) return _companyCache;
  const r = await fetch('/companies.json');
  if (!r.ok) throw new Error('Firma listesi yüklenemedi');
  _companyCache = await r.json();
  return _companyCache;
};
function CompanyPicker({ value, onChange }) {
  const [q, setQ] = useState(value || '');
  const [open, setOpen] = useState(false);
  const [list, setList] = useState(null);
  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState('');
  useEffect(() => { setQ(value || ''); }, [value]);

  const ensure = async () => {
    if (list || loading) return;
    setLoading(true); setErr('');
    try { setList(await loadCompanies()); }
    catch (e) { setErr('Liste yüklenemedi — elle yazabilirsiniz'); }
    finally { setLoading(false); }
  };
  const results = useMemo(() => {
    if (!list || !q.trim() || q.trim().length < 2) return [];
    const nq = normalizeTr(q);
    const out = [];
    for (let i = 0; i < list.length && out.length < 30; i++) {
      if (normalizeTr(list[i][0]).includes(nq)) out.push(list[i]);
    }
    return out;
  }, [list, q]);
  const exact = list && q.trim() && list.some(c => normalizeTr(c[0]) === normalizeTr(q));

  return (
    <div style={{ position: 'relative' }}>
      <label style={{ display: 'block', fontSize: '12px', color: '#94a3b8', marginBottom: '6px', fontWeight: '500' }}>Firma</label>
      <input
        value={q}
        onFocus={() => { setOpen(true); ensure(); }}
        onChange={e => { setQ(e.target.value); onChange(e.target.value); setOpen(true); ensure(); }}
        onBlur={() => setTimeout(() => setOpen(false), 180)}
        placeholder="Firma adı yazın — listeden seçin veya elle girin"
        style={{ width: '100%', padding: '10px 12px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '10px', color: '#e8f1f8', fontSize: '14px', boxSizing: 'border-box' }}
      />
      {open && q.trim().length >= 2 && (
        <div style={{ position: 'absolute', top: '100%', left: 0, right: 0, zIndex: 50, marginTop: '4px', background: '#0f2744', border: '1px solid rgba(255,255,255,0.15)', borderRadius: '10px', maxHeight: '260px', overflowY: 'auto', boxShadow: '0 8px 24px rgba(0,0,0,0.4)' }}>
          {loading && <div style={{ padding: '10px 12px', fontSize: '12px', color: '#64748b' }}>⏳ Firma listesi yükleniyor...</div>}
          {err && <div style={{ padding: '10px 12px', fontSize: '12px', color: '#f59e0b' }}>{err}</div>}
          {!loading && results.map((c, i) => (
            <div key={i} onMouseDown={() => { onChange(c[0]); setQ(c[0]); setOpen(false); }}
              style={{ padding: '8px 12px', cursor: 'pointer', borderBottom: '1px solid rgba(255,255,255,0.05)', fontSize: '12px', color: '#e8f1f8' }}
              onMouseEnter={e => e.currentTarget.style.background = 'rgba(59,130,246,0.15)'}
              onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
              {c[0]}
              {c[1] && <span style={{ color: '#64748b', marginLeft: '6px' }}>· Sicil {c[1]}</span>}
            </div>
          ))}
          {!loading && !err && results.length === 0 && <div style={{ padding: '8px 12px', fontSize: '12px', color: '#64748b' }}>Listede bulunamadı</div>}
          {!loading && !exact && q.trim().length >= 2 && (
            <div onMouseDown={() => { onChange(q.trim()); setOpen(false); }}
              style={{ padding: '9px 12px', cursor: 'pointer', fontSize: '12px', color: '#10b981', fontWeight: '600', background: 'rgba(16,185,129,0.08)', borderTop: '1px solid rgba(255,255,255,0.08)' }}>
              ➕ "{q.trim()}" olarak ekle (listede yok)
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ===== MÜŞTERİ LİNKİ: turdan bağımsız, her müşteriye kalıcı tek link (/m/<kod>, public/musteri.html) — tur linki (/b/) ayrı =====
// Kurumsal/bireysel satışlarda bilet, otel belgesi, vize vb. WhatsApp'a tek tek atmak yerine buradan gönderilir.
// Link tur linkiyle aynı sayfayı kullanır (belgeler, uçuş takibi, hava, kur, saat farkı, otel yol tarifi).
// Belgeler eklendikçe aynı link güncellenir; müşteriye yeniden göndermek gerekmez.
const CUST_DOC_TYPES = [['✈️', 'Uçak Bileti'], ['🛫', 'Biniş Kartı'], ['🏨', 'Otel Belgesi'], ['🛂', 'Vize'], ['🛡️', 'Seyahat Sigortası'], ['🎫', 'Fuar / Etkinlik Bileti'], ['📄', 'Diğer']];
const newLinkToken = () => {
  const abc = 'abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  return Array.from(crypto.getRandomValues(new Uint8Array(16)), b => abc[b % abc.length]).join('');
};
// Okunabilir müşteri linki: /m/onder-tasci-k7m2q — isim + 5 karakterlik gizli ek (≈33 milyon olasılık).
// Sadece isim olsaydı herkes başkasının adını yazıp belgelerine ulaşabilirdi (KVKK); ek bunu engeller.
const customerLinkSlug = (c) => {
  const base = asciiTr(`${c.firstName || ''} ${c.lastName || ''}`).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40) || 'musteri';
  const abc = 'abcdefghjkmnpqrstuvwxyz23456789';
  const tail = Array.from(crypto.getRandomValues(new Uint8Array(5)), x => abc[x % abc.length]).join('');
  return `${base}-${tail}`;
};
// Bilet PDF metninden uçuşları çıkar: "Ankara (ESB) Baku (GYD) VF-577 14/10/2026 12:15 15:30"
// ===== Belgeden bilgi okuma: otel giriş belgesi + isim kontrolü =====
// PDF metni tek satır gelir (satır sonu yok) → etiketlerden sonra gelen değer, bir sonraki etikete kadar alınır.
const AYLAR_TR_EN = { ocak: 1, subat: 2, mart: 3, nisan: 4, mayis: 5, haziran: 6, temmuz: 7, agustos: 8, eylul: 9, ekim: 10, kasim: 11, aralik: 12,
  january: 1, february: 2, march: 3, april: 4, may: 5, june: 6, july: 7, august: 8, september: 9, october: 10, november: 11, december: 12,
  jan: 1, feb: 2, mar: 3, apr: 4, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12, oca: 1, sub: 2, nis: 4, haz: 6, tem: 7, agu: 8, eyl: 9, eki: 10, kas: 11, ara: 12,
  januar: 1, februar: 2, marz: 3, mai: 5, juni: 6, juli: 7, oktober: 10, dezember: 12 };
// Metindeki tarihleri sırasıyla bulur → [{ ymd, idx }]
const datesIn = (text) => {
  const t = asciiTr(String(text || '')).toLowerCase();
  const out = [];
  const ok = (y, m, d) => y >= 2000 && y <= 2100 && m >= 1 && m <= 12 && d >= 1 && d <= 31;
  const push = (y, m, d, idx) => { if (ok(y, m, d)) out.push({ ymd: `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`, idx }); };
  let m;
  const r1 = /\b(\d{1,2})[./-](\d{1,2})[./-](\d{4})\b/g; while ((m = r1.exec(t))) push(+m[3], +m[2], +m[1], m.index);
  const r2 = /\b(\d{4})-(\d{1,2})-(\d{1,2})\b/g; while ((m = r2.exec(t))) push(+m[1], +m[2], +m[3], m.index);
  const r3 = /\b(\d{1,2})\.?\s+([a-z]{3,9})\.?,?\s+(\d{4})\b/g; while ((m = r3.exec(t))) { const mo = AYLAR_TR_EN[m[2]]; if (mo) push(+m[3], mo, +m[1], m.index); }
  const r4 = /\b([a-z]{3,9})\.?\s+(\d{1,2}),?\s+(\d{4})\b/g; while ((m = r4.exec(t))) { const mo = AYLAR_TR_EN[m[1]]; if (mo) push(+m[3], mo, +m[2], m.index); }
  return out.sort((a, b) => a.idx - b.idx);
};
const daysBetween = (a, b) => Math.round((new Date(b + 'T12:00:00') - new Date(a + 'T12:00:00')) / 86400000);
// Otel giriş belgesi / voucher / rezervasyon onayı → { name, address, checkIn, checkOut } (bulunamayan alan boş)
const detectHotel = (text) => {
  const raw = String(text || '').replace(/\s+/g, ' ');
  if (!raw.trim()) return null;
  const low = asciiTr(raw).toLowerCase();
  const STOPW = 'address|adres|adresse|check|giri[sş]|[cç][ıi]k[ıi][sş]|arrival|departure|tel|telefon|phone|e-?mail|www|room|oda|booking|rezervasyon|reservation|confirmation|guest|misafir|nights?|gece|city|[sş]ehir|country|[uü]lke';
  const STOP = '(?=\\s+(?:' + STOPW + ')(?![a-zçğıöşü])|\\s{2,}|$)';
  const grab = (re) => { const m = raw.match(re); return m ? m[1].replace(/[\s,;:|-]+$/, '').trim() : ''; };
  let name = grab(new RegExp('(?:hotel\\s*name|otel\\s*ad[ıi]|property(?:\\s*name)?|accommodation|konaklama\\s*yeri|hotel|otel)\\s*[:：]\\s*(.{3,80}?)' + STOP, 'i'));
  if (!name) {
    const m = raw.match(/((?:[A-ZÇĞİÖŞÜ][\wÇĞİÖŞÜçğıöşü&'.-]*\s){0,4}(?:Hotel|HOTEL|Otel|OTEL|Resort|RESORT|Suites?|SUITES?|Hostel|Palace|PALACE)(?:\s(?:[A-ZÇĞİÖŞÜ][\wÇĞİÖŞÜçğıöşü&'.-]*)){0,4})/);
    if (m && m[1].trim().split(/\s+/).length >= 2) name = m[1].trim();
  }
  // Sona yapışan etiket kelimelerini at ("… City Hotel Address")
  const stopEnd = new RegExp('\\s+(?:' + STOPW + ')$', 'i');
  for (let k = 0; k < 3 && stopEnd.test(name); k++) name = name.replace(stopEnd, '');
  name = name.replace(/\s+(?:\*+|★+)\s*$/, '').trim().slice(0, 80);
  const address = grab(new RegExp('(?:address|adres|adresse|anschrift)\\s*[:：]?\\s*(.{6,120}?)' + STOP, 'i')).slice(0, 120);
  // Giriş / çıkış: etiketten sonraki ilk tarih (en fazla 80 karakter ileride)
  const all = datesIn(raw);
  const after = (re) => { const m = re.exec(low); if (!m) return ''; const d = all.find(x => x.idx >= m.index && x.idx - m.index < 80); return d ? d.ymd : ''; };
  let checkIn = after(/check[\s-]?in|giris(?:\s*tarihi)?|arrival(?:\s*date)?|anreise|varis\s*tarihi/);
  let checkOut = after(/check[\s-]?out|cikis(?:\s*tarihi)?|departure(?:\s*date)?|abreise|ayrilis/);
  if (!checkIn || !checkOut || daysBetween(checkIn, checkOut) <= 0) {
    // Etiket yoksa: belgedeki ardışık tarih çifti (1–60 gece)
    for (let i = 0; i < all.length - 1 && !(checkIn && checkOut && daysBetween(checkIn, checkOut) > 0); i++) {
      for (let j = i + 1; j < all.length; j++) { const n = daysBetween(all[i].ymd, all[j].ymd); if (n >= 1 && n <= 60) { checkIn = all[i].ymd; checkOut = all[j].ymd; break; } }
    }
  }
  if (!(checkIn && checkOut && daysBetween(checkIn, checkOut) > 0)) { checkIn = checkIn || ''; checkOut = ''; }
  if (!name && !checkIn) return null;
  return { name, address, checkIn, checkOut };
};
// Levenshtein (kısa kelimeler için)
const lev = (a, b) => {
  if (a === b) return 0; const m = a.length, n = b.length; if (!m || !n) return m || n;
  let prev = Array.from({ length: n + 1 }, (_, j) => j);
  for (let i = 1; i <= m; i++) { const cur = [i]; for (let j = 1; j <= n; j++) cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)); prev = cur; }
  return prev[n];
};
// Belgedeki isim, müşterinin CRM'deki (pasaporttaki) adıyla aynı mı? Türkçe karaktersiz yazım hata sayılmaz (TAŞÇI = TASCI).
// Döner: { level: 'ok' | 'warn' | 'err' | 'none', msg }
const nameCheck = (c, text) => {
  if (!c) return { level: 'none', msg: '' };
  if (!String(text || '').trim()) return { level: 'none', msg: 'Görsel — isim kontrol edilemedi, gözle bakın' };
  const docW = [...nameWords(text)];
  const doc = new Set(docW);
  const toks = (s) => asciiTr(String(s || '')).toUpperCase().replace(/[^A-Z]+/g, ' ').split(' ').filter(w => w.length > 1);
  const firsts = toks(c.firstName), lasts = toks(c.lastName);
  const check = (t) => {
    if (doc.has(t)) return { ok: true };
    // Bitişik yazım: "ONDERMR", "AHMETCAN" (iki ad birleşik)
    if (docW.some(w => w.length > t.length && w.length - t.length <= 12 && (w.startsWith(t) || w.endsWith(t)))) return { ok: true };
    let best = null;
    docW.forEach(w => { if (Math.abs(w.length - t.length) > 2) return; const d = lev(w, t); if (!best || d < best.d) best = { w, d }; });
    const lim = t.length >= 6 ? 2 : t.length >= 4 ? 1 : 0;
    if (best && best.d > 0 && best.d <= lim) return { typo: best.w };
    return { missing: true };
  };
  const errs = [], warns = [];
  lasts.forEach(t => { const r = check(t); if (r.typo) warns.push(`soyad "${r.typo}" yazılmış, CRM'de "${t}"`); else if (r.missing) errs.push(`soyad "${t}" belgede yok`); });
  firsts.forEach((t, i) => { const r = check(t); if (r.typo) warns.push(`ad "${r.typo}" yazılmış, CRM'de "${t}"`); else if (r.missing) (i === 0 ? errs : warns).push(i === 0 ? `ad "${t}" belgede yok` : `ikinci ad "${t}" belgede yok`); });
  if (errs.length) return { level: 'err', msg: '⛔ ' + errs.join(' · ') + ' — belge bu kişiye ait olmayabilir' };
  if (warns.length) return { level: 'warn', msg: '⚠️ ' + warns.join(' · ') };
  return { level: 'ok', msg: '✓ İsim belgeyle aynı' };
};
const NAMECHK_COLOR = { ok: '#10b981', warn: '#f59e0b', err: '#ef4444', none: '#94a3b8' };

// Belge linkten kaldırılınca ondan okunan bilgiler de kalkar: uçuşlar (docId) ve otel (hotelDocId).
// Eski kayıtlarda kaynak bilgisi yok: o türden hiç belge kalmadıysa kaynaksız uçuş/otel de temizlenir.
const tripWithoutDoc = (trip, d) => {
  const docs = (trip.docs || []).filter(x => x.id !== d.id);
  const noTicketLeft = !docs.some(x => x.icon === '✈️' || x.icon === '🛫' || x.icon === '🛬');
  const flights = (trip.flights || []).filter(f => f.docId ? f.docId !== d.id : !(noTicketLeft && d.icon === '✈️'));
  const t = { ...trip, docs, flights };
  const noHotelLeft = !docs.some(x => x.icon === '🏨');
  if ((trip.hotelDocId && trip.hotelDocId === d.id) || (!trip.hotelDocId && d.icon === '🏨' && noHotelLeft)) {
    Object.assign(t, { hotelName: '', hotelAddress: '', hotelCheckIn: '', hotelCheckOut: '', hotelDocId: '' });
  }
  // Tarih/şehir/başlık kalan uçuş/otelden yeniden
  if (flights.length) {
    t.startDate = flights[0].ymd || t.startDate; t.endDate = flights[flights.length - 1].ymd || t.endDate;
    t.city = flights[0].toCity || t.city; t.title = `${flights[0].fromCity || ''} → ${flights[0].toCity || ''}`.trim();
  } else if (t.hotelCheckIn) { t.startDate = t.hotelCheckIn; t.endDate = t.hotelCheckOut || t.hotelCheckIn; t.title = t.hotelName || ''; }
  else if (!flights.length && !t.hotelName) { t.startDate = ''; t.endDate = ''; t.city = ''; t.title = ''; }
  return t;
};
// Linkteki bir belgeyi (URL'den) yeniden oku — tür sonradan değiştirilince
const pdfUrlText = async (url) => { const r = await fetch(url); if (!r.ok) throw new Error('indirilemedi'); const b = await r.blob(); return pdfFileText(new File([b], 'belge.pdf', { type: 'application/pdf' })); };

// Yedek uçuş okuyucu (farklı havayolu formatları): uçuş kodunu bul, çevresinde havalimanı kodları + tarih + saat ara
const AIRPORTS = new Set(('IST SAW ESB ADB AYT DLM BJV GZP TZX GZT ADA COV ASR VAN ERZ ERC DIY SZF KYA MLX EZS NAV HTY KCM KSY MQM BAL BGG GNY NKT IGD AJI KFS ONQ SFQ USQ YEI EDO CKZ TEQ DNZ ISE MSR OGU NOP VAS TJK KCO AOE AFY BZI YKO RZV GKD KZR CII BDM BXN SXZ ECN '
  + 'GYD NAJ TBS BUS EVN ALA NQZ TSE TAS SKD FRU DYU ASB FRA MUC BER DUS CGN HAM STR HAJ NUE LEJ DTM FMM CDG ORY NCE LYS MRS BSL LHR LGW STN LTN MAN BHX EDI DUB AMS EIN RTM BRU CRL LUX '
  + 'FCO CIA MXP BGY LIN VCE BLQ NAP PSA FLR BCN MAD AGP PMI VLC LIS OPO VIE ZRH GVA CPH ARN OSL HEL PRG BUD WAW KRK OTP SOF BEG SKP TIA SJJ LJU ZAG ATH SKG LCA ECN KBP '
  + 'DXB DWC AUH SHJ DOH BAH KWI MCT JED RUH DMM MED CAI HRG SSH TLV AMM BEY TUN ALG CMN RAK JFK EWR LAX ORD MIA IAD BOS YYZ YUL PEK PKX PVG CAN HKG ICN NRT HND BKK SIN KUL DEL BOM').split(' '));
const detectFlightsLoose = (text) => {
  const raw = String(text || '').replace(/\s+/g, ' ');
  const out = [], seen = new Set();
  const re = /\b(TK|PC|VF|XQ|XC|J2|LH|AF|KL|BA|EK|QR|FZ|EY|W6|FR|U2|SU|A3|OS|LX|LO|KC|HY|G9|SV|MS|RJ|AZ|IB|VY|TP|SK|AY|PS|ZF|DE|EW)\s?-?\s?(\d{2,4})\b/g;
  let m;
  while ((m = re.exec(raw))) {
    const code = m[1] + m[2];
    const win = raw.slice(Math.max(0, m.index - 220), m.index + 260);
    const rel = m.index - Math.max(0, m.index - 220);
    // Havalimanı kodları: önce parantez içi "(ESB)", yoksa bilinen kodlar
    let iatas = [...win.matchAll(/\(([A-Z]{3})\)/g)].map(x => ({ c: x[1], i: x.index }));
    if (iatas.length < 2) iatas = [...win.matchAll(/\b([A-Z]{3})\b/g)].map(x => ({ c: x[1], i: x.index })).filter(x => AIRPORTS.has(x.c));
    // Önce uçuş kodundan SONRA gelen ilk iki farklı havalimanı (dönüş uçuşu öncekinin kodlarını almasın); yetmezse en yakınlar
    const firstTwo = (list) => { const u = []; list.forEach(x => { if (u.length < 2 && !u.some(y => y.c === x.c)) u.push(x); }); return u; };
    let pair = firstTwo(iatas.filter(x => x.i > rel));
    if (pair.length < 2) {
      const uniq = []; iatas.forEach(x => { if (!uniq.some(y => y.c === x.c)) uniq.push(x); });
      pair = uniq.map(x => ({ ...x, d: Math.abs(x.i - rel) })).sort((a, b) => a.d - b.d).slice(0, 2).sort((a, b) => a.i - b.i);
    }
    if (pair.length < 2) continue;
    const ds = datesIn(win);
    const dd = ds.filter(x => x.idx > rel).sort((a, b) => a.idx - b.idx)[0] || ds.sort((a, b) => Math.abs(a.idx - rel) - Math.abs(b.idx - rel))[0];
    if (!dd) continue;
    const times = [...win.slice(rel).matchAll(/\b([01]?\d|2[0-3]):([0-5]\d)\b/g)].map(x => x[0]);
    const key = code + dd.ymd; if (seen.has(key)) continue; seen.add(key);
    const cityBefore = (iata) => { const mm = win.match(new RegExp("([A-Za-zÇĞİÖŞÜçğıöşü][A-Za-zÇĞİÖŞÜçğıöşü'-]{2,25})\\s*\\(" + iata + "\\)")); return mm ? mm[1] : ''; };
    out.push({ code, ymd: dd.ymd, fromCity: cityBefore(pair[0].c), from: pair[0].c, toCity: cityBefore(pair[1].c), to: pair[1].c, dep: times[0] || '', arr: times[1] || '' });
  }
  return out;
};

// Uçuş numarası olmayan belgeler (ör. THY koltuk/ek hizmet onayı): "İzmir (ADB) - Guangzhou (CAN) 16 Ekim 2026 21:50 … 16:50"
const AIRLINE_NAMES = [[/T[üu]rk Hava Yollar[ıi]|Turkish Airlines|\bTHY\b/i, 'THY'], [/Pegasus/i, 'Pegasus'], [/\bAJet\b/i, 'AJet'], [/SunExpress/i, 'SunExpress'], [/Lufthansa/i, 'Lufthansa'], [/Azerbaijan Airlines|AZAL/i, 'AZAL']];
const detectFlightsRoute = (text) => {
  const raw = String(text || '').replace(/\s+/g, ' ');
  const airline = (AIRLINE_NAMES.find(([re]) => re.test(raw)) || [])[1] || '';
  const re = /([A-Za-zÇĞİÖŞÜçğıöşü][A-Za-zÇĞİÖŞÜçğıöşü.'-]{1,25}(?: [A-Za-zÇĞİÖŞÜçğıöşü.'-]{2,25}){0,2})\s*\(([A-Z]{3})\)\s*[-–—>]+\s*([A-Za-zÇĞİÖŞÜçğıöşü][A-Za-zÇĞİÖŞÜçğıöşü.'-]{1,25}(?: [A-Za-zÇĞİÖŞÜçğıöşü.'-]{2,25}){0,2})\s*\(([A-Z]{3})\)/g;
  const ms = [...raw.matchAll(re)];
  const out = [], seen = new Set();
  ms.forEach((m, k) => {
    const start = m.index + m[0].length;
    const seg = raw.slice(start, Math.min(k + 1 < ms.length ? ms[k + 1].index : raw.length, start + 220));
    const d = datesIn(seg)[0];
    if (!d || d.idx > 40) return;
    const times = [...seg.matchAll(/\b([01]?\d|2[0-3]):([0-5]\d)\b/g)].map(x => x[0]);
    const cm = seg.match(/\b(TK|PC|VF|XQ|J2|LH|AJ)\s?-?\s?(\d{2,4})\b/);
    const key = m[2] + m[4] + d.ymd; if (seen.has(key)) return; seen.add(key);
    const last = (x) => String(x).trim().split(/\s+/).pop();
    out.push({ code: cm ? cm[1] + cm[2] : '', airline, ymd: d.ymd, fromCity: last(m[1]), from: m[2], toCity: last(m[3]), to: m[4], dep: times[0] || '', arr: times[1] || '' });
  });
  return out;
};
// Acente / GDS e-bilet tablosu (THY ve çoğu havayolu): "SOFIA/SOF ISTANBUL/IST TK 1032 H 05-10 15:50 05-10 17:20"
// Tarihte yıl yok → bilet düzenlenme tarihinden ("02OCT26" / "02EKİM26"); uçuş ayı daha önceyse ertesi yıl
const MON3 = { JAN: 1, FEB: 2, MAR: 3, APR: 4, MAY: 5, JUN: 6, JUL: 7, AUG: 8, SEP: 9, OCT: 10, NOV: 11, DEC: 12, OCA: 1, SUB: 2, NIS: 4, MAY_: 5, HAZ: 6, TEM: 7, AGU: 8, EYL: 9, EKI: 10, KAS: 11, ARA: 12 };
const detectFlightsGDS = (text) => {
  const raw = String(text || '').replace(/\s+/g, ' ');
  const up = asciiTr(raw).toUpperCase();
  let issueY = new Date().getFullYear(), issueM = new Date().getMonth() + 1;
  const im = up.match(/\b(\d{2})(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC|OCAK|SUBAT|MART|NISAN|MAYIS|HAZIRAN|TEMMUZ|AGUSTOS|EYLUL|EKIM|KASIM|ARALIK)(\d{2})\b/);
  if (im) { issueY = 2000 + +im[3]; issueM = MON3[im[2].slice(0, 3)] || issueM; }
  // Şehir: en az 2 harfli kelimeler (önceki satırın sonundaki "W C" gibi tek harfler karışmasın)
  const re = /\*?([A-ZÇĞİÖŞÜ][A-ZÇĞİÖŞÜ'.-]{1,24}(?: [A-ZÇĞİÖŞÜ][A-ZÇĞİÖŞÜ'.-]{1,24}){0,2})\/([A-Z]{3})\s+\*?([A-ZÇĞİÖŞÜ][A-ZÇĞİÖŞÜ'.-]{1,24}(?: [A-ZÇĞİÖŞÜ][A-ZÇĞİÖŞÜ'.-]{1,24}){0,2})\/([A-Z]{3})\s+([A-Z0-9]{2})\s+(\d{1,4})\s+[A-Z]\s+(\d{2})-?(\d{2}|[A-Z]{3})\s+(\d{1,2}:?\d{2})\s+(?:(\d{2})-?(\d{2}|[A-Z]{3})\s+)?(\d{1,2}:?\d{2})/g;
  const out = [], seen = new Set();
  let m;
  const tm = (t) => t.includes(':') ? t : t.slice(0, -2) + ':' + t.slice(-2);
  while ((m = re.exec(raw))) {
    const d = +m[7], mo = /\d/.test(m[8]) ? +m[8] : (MON3[asciiTr(m[8]).toUpperCase()] || 0);
    if (!mo || d < 1 || d > 31) continue;
    const y = mo < issueM - 1 ? issueY + 1 : issueY;
    const ymd = `${y}-${String(mo).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
    const code = m[5] + m[6];
    if (seen.has(code + ymd)) continue; seen.add(code + ymd);
    // Biletteki şehirler ASCII büyük harf: Türkçe küçültme "SOFIA"yı "Sofıa" yapmasın
    const tc = (x) => x.trim().toLowerCase().replace(/(^|[\s-])(\S)/g, (q, a, b) => a + b.toUpperCase());
    out.push({ code, ymd, fromCity: tc(m[1]), from: m[2], toCity: tc(m[3]), to: m[4], dep: tm(m[9]), arr: tm(m[12]) });
  }
  return out;
};
const detectFlights = (text) => {
  const strict = detectFlightsStrict(text);
  if (strict.length) return strict;
  const gds = detectFlightsGDS(text);
  if (gds.length) return gds;
  const loose = detectFlightsLoose(text);
  return loose.length ? loose : detectFlightsRoute(text);
};
// Aynı uçuş mu? (numara yoksa güzergah + tarih)
const sameFlight = (a, b) => a.ymd === b.ymd && (a.code && b.code ? a.code === b.code : a.from === b.from && a.to === b.to);
const detectFlightsStrict = (text) => {
  const out = [], seen = new Set();
  const re = /([A-Za-zÇĞİÖŞÜçğıöşü][A-Za-zÇĞİÖŞÜçğıöşü .'-]{1,30}?)\s*\(([A-Z]{3})\)\s+([A-Za-zÇĞİÖŞÜçğıöşü][A-Za-zÇĞİÖŞÜçğıöşü .'-]{1,30}?)\s*\(([A-Z]{3})\)\s+([A-Z0-9]{2})\s?-?\s?(\d{1,4})\s+(\d{2})[/.](\d{2})[/.](\d{4})\s+(\d{1,2}:\d{2})\s+(\d{1,2}:\d{2})/g;
  let m;
  while ((m = re.exec(String(text || '').replace(/\s+/g, ' ')))) {
    const code = `${m[5]}${m[6]}`, ymd = `${m[9]}-${m[8]}-${m[7]}`;
    if (seen.has(code + ymd)) continue; seen.add(code + ymd);
    // Şehir adının önüne PDF başlıkları ("ARRIVAL TIME Varış Saati Ankara") karışabiliyor → son kelime
    const city = (x) => String(x).trim().split(/\s+/).pop();
    out.push({ code, ymd, fromCity: city(m[1]), from: m[2], toCity: city(m[3]), to: m[4], dep: m[10], arr: m[11] });
  }
  return out;
};

// Müşteri linkini yayınla: paylasimlar/<kod> + müşteri kartına shareToken/shareTrip. Hem tek tek (Müşteri Linki)
// hem toplu belge yüklemede kullanılır. Döner: { link, text } (WhatsApp mesajı şablondan)
const publishCustomerLink = async (c, trip, token, appSettings) => {
      const name = `${titleCaseTr(c.firstName)} ${titleCaseTr(c.lastName)}`.trim();
      const fl = (trip.flights || []).filter(f => /^[A-Z0-9]{2}\d{1,4}$/.test(String(f.code || '').toUpperCase().replace(/[\s-]/g, '')) || (!f.code && f.from && f.to && f.ymd));
      const flights = fl.map((f, i) => ({
        dir: fl.length === 2 ? (i === 0 ? 'Gidiş' : 'Dönüş') : 'Uçuş',
        code: String(f.code || '').toUpperCase().replace(/[\s-]/g, ''), airline: f.airline || '',
        date: f.ymd ? formatDate(f.ymd) : '', ymd: f.ymd || '', // ymd: linkte sıradaki uçuşu bulmak için
        dep: [f.fromCity, f.from].filter(Boolean).join(' ') + (f.dep ? ` · ${f.dep}` : ''),
        arr: [f.toCity, f.to].filter(Boolean).join(' ') + (f.arr ? ` · ${f.arr}` : ''),
      }));
      const docs = (trip.docs || []).map(d => ({ icon: d.icon, label: d.label, url: d.url, addedAt: d.addedAt || '' })); // addedAt: linkte aya göre gruplama
      await setDoc(doc(db, 'paylasimlar', token), {
        kind: 'customer', customerName: name, tourName: trip.title || '', country: trip.country || '', city: trip.city || '',
        startDate: trip.startDate || '', endDate: trip.endDate || '', docs, flights,
        hotel: trip.hotelName ? { name: trip.hotelName, address: trip.hotelAddress || '', city: trip.city || '', country: trip.country || '', phone: '', checkIn: trip.hotelCheckIn || '', checkOut: trip.hotelCheckOut || '' } : null,
        contact: { phone: appSettings?.shareContact?.phone || '+90 258 263 71 76', whatsapp: appSettings?.shareContact?.whatsapp || '', instagram: appSettings?.shareContact?.instagram ?? 'paydostur' },
        customerDocId: c._docId || String(c.id), // PIN belirlenince sunucu müşteri kartına yazar (linkPin)
        updatedAt: new Date().toISOString(),
      }, { merge: true }); // merge: müşterinin belirlediği PIN güncellemede silinmesin
      const shareTrip = JSON.stringify(trip);
      await setDoc(doc(db, 'customers', c._docId || String(c.id)), { shareToken: token, shareTrip }, { merge: true });
      const link = `${window.location.origin}/m/${token}`;
      const belgeler = [...docs.map(d => d.label), ...(flights.length ? ['Uçuş Takibi'] : [])].filter((x, i, a) => a.indexOf(x) === i).join(', ');
      const tpl = (appSettings?.shareMessageTemplate || '').trim() || DEFAULT_SHARE_MSG;
      let text = tpl.replace(/\{isim\}/g, name).replace(/\{tur\}/g, trip.title || 'Seyahatiniz').replace(/\{belgeler\}/g, belgeler).replace(/\{link\}/g, link);
      if (!text.includes(link)) text += `\n${link}`;
  return { link, text };
};

// Müşteri linki PIN'i: müşteri ilk açılışta kendisi belirler, sunucu (Firebase fonksiyonu "belge") kartımıza linkPin olarak yazar.
// Kaybederse buradan söyleriz; "Sıfırla" ile müşteri yeniden belirler, "PIN ver" ile biz koyarız.
// Hash biçimi sunucuyla aynı: sha256("<salt>:<pin>") hex.
const sha256Hex = async (str) => Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(str)))).map(b => b.toString(16).padStart(2, '0')).join('');
function LinkPinBar({ c, showToast }) {
  const docId = c._docId || String(c.id);
  const [live, setLive] = useState({ linkPin: c.linkPin || '', shareToken: c.shareToken || '' });
  const [show, setShow] = useState(false);
  useEffect(() => onSnapshot(doc(db, 'customers', docId), snap => {
    const d = snap.data() || {};
    setLive({ linkPin: d.linkPin || '', shareToken: d.shareToken || '' });
  }, () => {}), [docId]);
  if (!live.shareToken) return null;
  const setPin = async (pin) => {
    const now = new Date().toISOString();
    const ref = doc(db, 'paylasimlar', live.shareToken);
    if (pin) {
      const salt = Array.from(crypto.getRandomValues(new Uint8Array(8))).map(b => b.toString(16).padStart(2, '0')).join('');
      await setDoc(ref, { pinHash: await sha256Hex(`${salt}:${pin}`), pinSalt: salt, pinFails: 0, pinLockUntil: 0, pinSetAt: now }, { merge: true });
    } else {
      await setDoc(ref, { pinHash: deleteField(), pinSalt: deleteField(), pinFails: 0, pinLockUntil: 0 }, { merge: true });
    }
    await setDoc(doc(db, 'customers', docId), { linkPin: pin || '', linkPinSetAt: pin ? now : '' }, { merge: true });
  };
  const reset = async () => {
    if (!window.confirm('PIN sıfırlansın mı? Müşteri linki bir sonraki açışında yeni PIN belirleyecek.')) return;
    try { await setPin(''); showToast?.('PIN sıfırlandı — müşteri yeni PIN belirleyecek', 'success'); } catch (e) { showToast?.('PIN sıfırlanamadı: ' + e.message, 'error'); }
  };
  const give = async () => {
    const pin = (window.prompt('Müşteriye verilecek 4 haneli PIN:', '') || '').trim();
    if (!pin) return;
    if (!/^\d{4}$/.test(pin)) { showToast?.('PIN 4 rakam olmalı', 'error'); return; }
    try { await setPin(pin); setShow(true); showToast?.('PIN kaydedildi', 'success'); } catch (e) { showToast?.('PIN kaydedilemedi: ' + e.message, 'error'); }
  };
  const btn = { background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.12)', borderRadius: '8px', padding: '6px 10px', color: '#cbd5e1', cursor: 'pointer', fontSize: '12px' };
  return (
    <div style={{ margin: '12px 20px 0', padding: '10px 14px', background: 'rgba(34,197,94,0.06)', border: '1px solid rgba(34,197,94,0.25)', borderRadius: '12px', display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap' }}>
      <span style={{ fontSize: '13px', color: '#94a3b8' }}>🔐 Link PIN:</span>
      {live.linkPin
        ? <b onClick={() => setShow(v => !v)} title="Göster / gizle" style={{ fontSize: '16px', letterSpacing: '4px', color: '#22c55e', cursor: 'pointer', fontFamily: 'monospace' }}>{show ? live.linkPin : '••••'}</b>
        : <span style={{ fontSize: '12px', color: '#eab308' }}>henüz belirlenmedi — müşteri linki ilk açtığında kendisi belirleyecek</span>}
      <span style={{ flex: 1 }} />
      {live.linkPin && <button onClick={() => setShow(v => !v)} style={btn}>{show ? '🙈 Gizle' : '👁 Göster'}</button>}
      <button onClick={give} style={btn}>✏️ PIN ver</button>
      {live.linkPin && <button onClick={reset} style={{ ...btn, color: '#f87171', borderColor: 'rgba(239,68,68,0.3)' }}>↺ Sıfırla</button>}
    </div>
  );
}

// ===== TAVSİYELER: şehir bazlı tavsiye restoranlar (Firestore: tavsiyeler/<şehir-anahtarı>) =====
// Bir şehir bir kez girilir; o şehre giden her turun linki (/b/) açıldığında güncel haliyle okur — tekrar paylaşım gerekmez.
// Şehir anahtarı: "Bakü" / "Baku" / "BAKU" → "baku" (belgeler.html'deki cityKey ile aynı olmalı)
const cityKey = (s) => String(s || '').trim().toLocaleLowerCase('tr-TR')
  .replace(/[çğıöşü]/g, ch => ({ 'ç': 'c', 'ğ': 'g', 'ı': 'i', 'ö': 'o', 'ş': 's', 'ü': 'u' }[ch]))
  .normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60);
// Tur şehri birden fazla olabilir: "Milano, Venedik" / "Paris - Brüksel"
const tourCities = (str) => String(str || '').split(/\s*(?:,|\/|;|\s[-–—]\s|\+)\s*/).map(x => x.trim()).filter(Boolean);
const EMPTY_REST = { name: '', cuisine: '', price: '', note: '', address: '' };
// ===== 📣 Bildirimler: müşteri linkinden bildirime izin verenlere mesaj =====
// Sunucu: Firebase fonksiyonu "bildirim" (telegram-bot/functions/bildirim.js). Kampanya mesajı sadece kampanya
// onayı verenlere gider — bu kural sunucuda; buradaki sayılar sadece önizleme.
const BILDIRIM_API = 'https://europe-west1-paydos-crm.cloudfunctions.net/bildirim';
const bildirimCall = async (body) => {
  const token = auth.currentUser ? await auth.currentUser.getIdToken() : '';
  const r = await fetch(BILDIRIM_API, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` }, body: JSON.stringify(body) });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw new Error(j.error || `HTTP ${r.status}`);
  return j;
};
const custKey = (c) => c._docId || String(c.id);
const daysUntil = (ymd) => { const d = safeParseDate(ymd); return d ? Math.ceil((d - new Date()) / 86400000) : null; };
const BILDIRIM_HEDEF = [
  ['all', 'Bildirim açık herkes'],
  ['schengen60', 'Schengen vizesi 60 gün içinde bitenler'],
  ['usa90', 'ABD vizesi 90 gün içinde bitenler'],
  ['passport6', 'Pasaportu 6 ay içinde bitenler'],
  ['pick', 'Seçtiğim müşteriler'],
];
function BildirimlerModule({ customers, showToast, isMobile }) {
  const [stats, setStats] = useState(null);
  const [log, setLog] = useState([]);
  const [err, setErr] = useState('');
  const [type, setType] = useState('bilgi');
  const [hedef, setHedef] = useState('all');
  const [picked, setPicked] = useState([]);
  const [q, setQ] = useState('');
  const [title, setTitle] = useState('');
  const [body, setBody] = useState('');
  const [url, setUrl] = useState('');
  const [busy, setBusy] = useState(false);
  const toggleAuto = async () => {
    const on = !stats?.auto;
    try { await bildirimCall({ a: 'auto', on }); setStats(st => ({ ...st, auto: on })); showToast?.(on ? '⏰ Otomatik hatırlatma açıldı' : 'Otomatik hatırlatma kapatıldı', 'success'); }
    catch (e) { showToast?.('❌ ' + e.message, 'error'); }
  };
  const load = async () => {
    setErr('');
    try { const [s, l] = await Promise.all([bildirimCall({ a: 'stats' }), bildirimCall({ a: 'log' })]); setStats(s); setLog(l.items || []); }
    catch (e) { setErr(e.message); }
  };
  useEffect(() => { load(); }, []);
  const by = stats?.byCustomer || {};
  // Bildirimi açık müşteriler (CRM kartıyla eşleşen)
  const subCustomers = customers.filter(c => by[custKey(c)]);
  const matchHedef = (c) => {
    if (hedef === 'all') return true;
    if (hedef === 'pick') return picked.includes(custKey(c));
    if (hedef === 'schengen60') return safeParseJSON(c.schengenVisas).some(v => { const n = daysUntil(v.endDate); return n !== null && n >= 0 && n <= 60; });
    if (hedef === 'usa90') { const n = daysUntil(safeParseObj(c.usaVisa).endDate); return n !== null && n >= 0 && n <= 90; }
    if (hedef === 'passport6') return safeParseJSON(c.passports).some(p => { const n = daysUntil(p.expiryDate); return n !== null && n >= 0 && n <= 183; });
    return false;
  };
  const targets = subCustomers.filter(matchHedef);
  const devices = hedef === 'all'
    ? (type === 'kampanya' ? stats?.marketing || 0 : stats?.total || 0)
    : targets.reduce((n, c) => n + (type === 'kampanya' ? by[custKey(c)].m : by[custKey(c)].n), 0);
  const send = async () => {
    if (!title.trim() || !body.trim()) { showToast?.('Başlık ve mesaj yazın', 'warning'); return; }
    if (!devices) { showToast?.('Bu hedefte bildirim alacak cihaz yok', 'warning'); return; }
    if (!window.confirm(`${type === 'kampanya' ? '🎁 KAMPANYA' : 'ℹ️ Bilgilendirme'} bildirimi ${devices} cihaza gönderilsin mi?\n\n${title}\n${body}`)) return;
    setBusy(true);
    try {
      const r = await bildirimCall({ a: 'send', type, title, body, url: url.trim(), customerIds: hedef === 'all' ? null : targets.map(custKey) });
      showToast?.(`📣 ${r.sent} cihaza gönderildi${r.failed ? ` · ${r.failed} ulaşmadı` : ''}`, r.sent ? 'success' : 'warning');
      setTitle(''); setBody(''); setUrl(''); load();
    } catch (e) { showToast?.('❌ Gönderilemedi: ' + e.message, 'error'); }
    setBusy(false);
  };
  const inp = { width: '100%', padding: '10px 12px', background: 'rgba(0,0,0,0.25)', border: '1px solid rgba(255,255,255,0.12)', borderRadius: '8px', color: '#e8f1f8', fontSize: '14px', boxSizing: 'border-box' };
  const lbl = { display: 'block', fontSize: '12px', color: '#94a3b8', margin: '14px 0 6px', fontWeight: 600 };
  const card = { background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: '14px', padding: isMobile ? '16px' : '20px' };
  const pickList = subCustomers.filter(c => !q || `${c.firstName} ${c.lastName}`.toLocaleLowerCase('tr').includes(q.toLocaleLowerCase('tr'))).slice(0, 30);
  return (
    <div style={{ padding: isMobile ? '16px' : '24px', maxWidth: '1100px' }}>
      <h2 style={{ fontSize: '20px', margin: '0 0 6px' }}>📣 Bildirimler</h2>
      <p style={{ margin: '0 0 18px', fontSize: '13px', color: '#64748b' }}>Müşteri linkinden bildirime izin veren telefonlara mesaj gönderin. iPhone'da bildirim için linkin ana ekrana eklenmiş olması gerekir.</p>
      {err && <div style={{ ...card, borderColor: 'rgba(239,68,68,0.4)', color: '#fca5a5', marginBottom: '16px', fontSize: '13px' }}>Bildirim servisine ulaşılamadı: {err}. (Firebase fonksiyonu "bildirim" yüklü mü?)</div>}
      <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr 1fr' : 'repeat(3, 1fr)', gap: '12px', marginBottom: '18px' }}>
        {[['🔔', 'Bildirim açık cihaz', stats?.total, '#3b82f6'], ['🎁', 'Kampanya onaylı', stats?.marketing, '#f59e0b'], ['👥', 'Müşteri', subCustomers.length, '#10b981']].map(([i, l, v, c]) => (
          <div key={l} style={{ ...card, padding: '14px 16px' }}><div style={{ fontSize: '24px', fontWeight: 700, color: c }}>{stats ? v : '…'}</div><div style={{ fontSize: '12px', color: '#94a3b8' }}>{i} {l}</div></div>
        ))}
      </div>
      {/* ⏰ Otomatik hatırlatma — tarihler müşteri kartından (linkte görünen vize/pasaport bilgisiyle aynı) */}
      <div style={{ ...card, display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '16px', padding: '14px 18px', borderColor: stats?.auto ? 'rgba(16,185,129,0.35)' : 'rgba(255,255,255,0.08)' }}>
        <span style={{ fontSize: '24px' }}>⏰</span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontWeight: 700, fontSize: '14px' }}>Otomatik vize ve pasaport hatırlatması</div>
          <div style={{ fontSize: '12px', color: '#94a3b8', lineHeight: 1.5 }}>Her gün 10:00'da: vize bitimine <b>60 · 30 · 7 gün</b>, pasaport bitimine <b>6 ay · 3 ay</b> kala müşteriye kendiliğinden bildirim gider. Her hatırlatma bir kez gönderilir. Bildirimi açık olan herkese gider (bilgilendirmedir, reklam içermez).</div>
        </div>
        <button onClick={toggleAuto} disabled={!stats} style={{ flex: 'none', padding: '8px 16px', borderRadius: '999px', cursor: 'pointer', fontWeight: 700, fontSize: '13px', border: 'none', color: '#fff', background: stats?.auto ? '#10b981' : '#475569', opacity: stats ? 1 : 0.5 }}>{stats ? (stats.auto ? '✓ Açık' : 'Kapalı') : '…'}</button>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '3fr 2fr', gap: '16px', alignItems: 'start' }}>
        <div style={card}>
          <label style={{ ...lbl, marginTop: 0 }}>Tür</label>
          <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
            {[['bilgi', 'ℹ️ Bilgilendirme', 'Uçuş, otel, belge, tur duyurusu'], ['kampanya', '🎁 Kampanya', 'Sadece kampanya onayı verenlere']].map(([k, t, s]) => (
              <button key={k} onClick={() => setType(k)} style={{ flex: 1, minWidth: '180px', textAlign: 'left', padding: '10px 12px', borderRadius: '10px', cursor: 'pointer', color: '#e8f1f8', background: type === k ? 'rgba(59,130,246,0.18)' : 'rgba(0,0,0,0.2)', border: `1px solid ${type === k ? '#3b82f6' : 'rgba(255,255,255,0.1)'}` }}>
                <div style={{ fontWeight: 700, fontSize: '13px' }}>{t}</div><div style={{ fontSize: '11px', color: '#94a3b8' }}>{s}</div>
              </button>
            ))}
          </div>
          {type === 'kampanya' && <div style={{ marginTop: '8px', fontSize: '11.5px', color: '#fbbf24' }}>Reklam/kampanya içeriğini "Bilgilendirme" olarak göndermeyin — onay vermeyen müşteriye ticari ileti yasal risktir.</div>}
          <label style={lbl}>Kime</label>
          <select value={hedef} onChange={e => setHedef(e.target.value)} style={inp}>
            {BILDIRIM_HEDEF.map(([k, t]) => <option key={k} value={k}>{t}</option>)}
          </select>
          {hedef === 'pick' && (
            <div style={{ marginTop: '8px' }}>
              <input value={q} onChange={e => setQ(e.target.value)} placeholder="Müşteri ara (sadece bildirimi açık olanlar)" style={inp} />
              <div style={{ maxHeight: '180px', overflow: 'auto', marginTop: '6px', display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
                {pickList.map(c => { const k = custKey(c), on = picked.includes(k); return (
                  <button key={k} onClick={() => setPicked(p => on ? p.filter(x => x !== k) : [...p, k])} style={{ padding: '5px 10px', borderRadius: '999px', fontSize: '12px', cursor: 'pointer', color: '#e8f1f8', background: on ? 'rgba(16,185,129,0.25)' : 'rgba(255,255,255,0.05)', border: `1px solid ${on ? '#10b981' : 'rgba(255,255,255,0.12)'}` }}>
                    {on ? '✓ ' : ''}{c.firstName} {c.lastName}{by[k].m ? ' 🎁' : ''}
                  </button>); })}
                {!pickList.length && <span style={{ fontSize: '12px', color: '#64748b' }}>Bildirimi açık müşteri yok.</span>}
              </div>
            </div>
          )}
          <label style={lbl}>Başlık <span style={{ color: '#64748b', fontWeight: 400 }}>({title.length}/80)</span></label>
          <input value={title} maxLength={80} onChange={e => setTitle(e.target.value)} placeholder={type === 'kampanya' ? 'Kapadokya turunda erken rezervasyon' : 'Online check-in açıldı'} style={inp} />
          <label style={lbl}>Mesaj <span style={{ color: '#64748b', fontWeight: 400 }}>({body.length}/300)</span></label>
          <textarea value={body} maxLength={300} onChange={e => setBody(e.target.value)} rows={4} placeholder={type === 'kampanya' ? '15 Kasım\'a kadar %15 indirim. Detaylar için dokunun.' : 'Yarınki TK1032 uçuşunuz için online check-in açıldı.'} style={{ ...inp, resize: 'vertical', fontFamily: 'inherit' }} />
          <label style={lbl}>Dokununca açılacak sayfa <span style={{ color: '#64748b', fontWeight: 400 }}>(boşsa müşterinin kendi linki · sadece paydostur.com)</span></label>
          <input value={url} onChange={e => setUrl(e.target.value)} placeholder="https://paydostur.com/..." style={inp} />
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginTop: '18px', flexWrap: 'wrap' }}>
            <button onClick={send} disabled={busy || !stats} style={{ padding: '11px 22px', borderRadius: '10px', border: 'none', cursor: busy ? 'wait' : 'pointer', fontWeight: 700, fontSize: '14px', color: '#fff', background: type === 'kampanya' ? 'linear-gradient(135deg,#f59e0b,#d97706)' : 'linear-gradient(135deg,#3b82f6,#2563eb)', opacity: busy || !stats ? 0.6 : 1 }}>{busy ? 'Gönderiliyor…' : '📣 Gönder'}</button>
            <span style={{ fontSize: '13px', color: '#94a3b8' }}>{stats ? <><b style={{ color: '#e8f1f8' }}>{devices}</b> cihaz{hedef !== 'all' ? ` · ${targets.length} müşteri` : ''}</> : 'yükleniyor…'}</span>
          </div>
        </div>
        <div style={card}>
          <div style={{ fontSize: '12px', color: '#94a3b8', fontWeight: 600, marginBottom: '8px' }}>ÖNİZLEME</div>
          <div style={{ background: '#f8fafc', color: '#0f172a', borderRadius: '14px', padding: '12px 14px', display: 'flex', gap: '10px', boxShadow: '0 6px 20px rgba(0,0,0,0.3)' }}>
            <img src="/icons/icon-192.png" alt="" style={{ width: '36px', height: '36px', borderRadius: '8px', flex: 'none' }} />
            <div style={{ minWidth: 0 }}><div style={{ fontWeight: 700, fontSize: '13.5px' }}>{title || 'Başlık'}</div><div style={{ fontSize: '12.5px', color: '#475569', wordBreak: 'break-word' }}>{body || 'Mesajınız burada görünür.'}</div></div>
          </div>
          <div style={{ fontSize: '12px', color: '#94a3b8', fontWeight: 600, margin: '20px 0 8px', display: 'flex', justifyContent: 'space-between' }}><span>SON GÖNDERİLENLER</span><button onClick={load} style={{ background: 'none', border: 'none', color: '#60a5fa', cursor: 'pointer', fontSize: '12px' }}>↻ Yenile</button></div>
          {log.length ? log.map(x => (
            <div key={x.id} style={{ padding: '8px 0', borderTop: '1px solid rgba(255,255,255,0.06)', fontSize: '12px' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}><b style={{ color: '#e8f1f8' }}>{x.type === 'kampanya' ? '🎁' : 'ℹ️'} {x.title}</b><span style={{ color: '#64748b', whiteSpace: 'nowrap' }}>{String(x.at || '').slice(0, 16).replace('T', ' ')}</span></div>
              <div style={{ color: '#94a3b8' }}>{x.sent}/{x.matched} cihaz · {x.by === 'otomatik' ? '⏰ otomatik' : String(x.by || '').split('@')[0]}</div>
            </div>
          )) : <div style={{ fontSize: '12px', color: '#64748b' }}>Henüz gönderim yok.</div>}
        </div>
      </div>
    </div>
  );
}

// ===== 🏆 Tur bilgi yarışması (canlı) =====
// Rehber CRM'den yönetir; yolcular tur linkinden (/b/<kod>) katılır ve cevaplar. Firestore:
//   yarisma/<şehir>                      — soru bankası { city, questions: [{ q, o: [4 şık], a: doğru şık }] } (sadece CRM)
//   yarisma_oturum/<turId>               — canlı oturum (herkes okur; doğru cevap sadece "reveal"de yazılır)
//   yarisma_oturum/<turId>/gizli/sorular — oturumun soruları + cevapları (sadece CRM)
//   yarisma_oturum/<turId>/players/<link kodu> — oyuncu { name, answers: { i: { c, at } }, score, last }
// Puan sunucu saatine göre hesaplanır: doğru cevap 500–1000 (hızlı olan çok alır), süre bitince 0.
const YARISMA_SURE = 20; // saniye
const yarismaPuan = (ms, limitMs) => (ms > limitMs + 1500 ? 0 : Math.round(500 + 500 * Math.max(0, 1 - ms / limitMs)));
const validQ = (x) => x && String(x.q || '').trim() && Array.isArray(x.o) && x.o.length === 4 && x.o.every(s => String(s || '').trim()) && x.a >= 0 && x.a < 4;
const SIK_RENK = ['#ef4444', '#3b82f6', '#f59e0b', '#10b981'];
function YarismaModal({ tour, onClose, showToast, isMobile }) {
  const cities = tourCities(tour.city);
  const [city, setCity] = useState(cities[0] || tour.country || '');
  const key = cityKey(city);
  const [bank, setBank] = useState(null);
  const [edit, setEdit] = useState(false);
  const [aiBusy, setAiBusy] = useState(false);
  const sid = String(tour.id);
  const [ses, setSes] = useState(undefined);
  const [players, setPlayers] = useState([]);
  const [now, setNow] = useState(Date.now());
  const qsRef = useRef(null);
  const revealing = useRef(false);
  useEffect(() => { setBank(null); getDoc(doc(db, 'yarisma', key)).then(s => setBank(s.exists() ? (s.data().questions || []) : [])).catch(() => setBank([])); }, [key]);
  useEffect(() => {
    const u1 = onSnapshot(doc(db, 'yarisma_oturum', sid), s => setSes(s.exists() ? s.data() : null), () => setSes(null));
    const u2 = onSnapshot(collection(db, 'yarisma_oturum', sid, 'players'), q => setPlayers(q.docs.map(d => ({ id: d.id, ...d.data() }))), () => {});
    return () => { u1(); u2(); };
  }, [sid]);
  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 500); return () => clearInterval(t); }, []);
  const live = ses && ses.status !== 'closed';
  // Sayfa yenilenirse oturumun soruları gizli kopyadan geri gelir
  useEffect(() => { if (live && !qsRef.current) getDoc(doc(db, 'yarisma_oturum', sid, 'gizli', 'sorular')).then(s => { if (s.exists()) qsRef.current = s.data().questions || []; }).catch(() => {}); }, [live, sid]);

  const saveBank = async (qs) => {
    try { await setDoc(doc(db, 'yarisma', key), { city, questions: qs, updatedAt: new Date().toISOString() }); setBank(qs); showToast?.('Sorular kaydedildi', 'success'); }
    catch (e) { showToast?.('❌ Kaydedilemedi: ' + e.message, 'error'); }
  };
  const genAI = async () => {
    setAiBusy(true);
    try {
      const prompt = `${city}${tour.country ? ` (${tour.country})` : ''} gezisindeki Türk tur grubu için otobüste oynanacak 10 soruluk eğlenceli bilgi yarışması hazırla.
- Türkçe, kolay-orta zorluk: tarih, ünlü yapılar, yemek, kültur, gündelik ilginç bilgiler.
- Sadece KESİN doğru olduğundan emin olduğun bilgiler; şüpheli olanı sorma. Tarih/sayı sorularında şıklar birbirinden belirgin farklı olsun.
- Her soruda 4 şık, tek doğru. Doğru şıkkın yeri sorudan soruya değişsin. Soru en fazla 120, şık en fazla 40 karakter.
SADECE JSON dizi döndür: [{"q":"soru","o":["şık1","şık2","şık3","şık4"],"a":0}]  (a = doğru şıkkın sırası, 0-3)`;
      const resp = await claudeRequest({ method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ model: 'claude-sonnet-4-6', max_tokens: 2000, messages: [{ role: 'user', content: prompt }] }) });
      if (!resp.ok) throw new Error(`API ${resp.status}`);
      const data = await resp.json();
      const m = (data.content?.[0]?.text || '').match(/\[[\s\S]*\]/);
      if (!m) throw new Error('yanıt okunamadı');
      const qs = JSON.parse(m[0]).map(x => ({ q: String(x.q || ''), o: (x.o || []).slice(0, 4).map(String), a: Number(x.a) })).filter(validQ);
      if (!qs.length) throw new Error('geçerli soru yok');
      setBank(b => [...(b || []), ...qs]); setEdit(true);
      showToast?.(`🤖 ${qs.length} soru eklendi — kontrol edip Kaydet'e basın`, 'success');
    } catch (e) { showToast?.('Soru üretilemedi: ' + e.message, 'error'); }
    setAiBusy(false);
  };

  const openGame = async () => {
    const qs = (bank || []).filter(validQ);
    if (!qs.length) { showToast?.('Önce soru ekleyin', 'warning'); return; }
    try {
      // Tur linklerine tur kimliği (eski linklerde yok) — yolcunun sayfası yarışmayı buradan bulur
      const toks = (tour.reservations || []).filter(r => !r.cancelled && r.shareToken).map(r => r.shareToken);
      await Promise.all(toks.map(t => setDoc(doc(db, 'paylasimlar', t), { tourId: sid }, { merge: true }).catch(() => {})));
      const old = await getDocs(collection(db, 'yarisma_oturum', sid, 'players'));
      if (old.size) { const b = writeBatch(db); old.docs.forEach(d => b.delete(d.ref)); await b.commit(); }
      await setDoc(doc(db, 'yarisma_oturum', sid, 'gizli', 'sorular'), { questions: qs });
      qsRef.current = qs;
      await setDoc(doc(db, 'yarisma_oturum', sid), { status: 'lobby', title: `${city} Bilgi Yarışması`, tourName: tour.name || '', total: qs.length, qIndex: -1, limit: YARISMA_SURE, q: null, correct: null, top: [], createdAt: serverTimestamp() });
      if (!toks.length) showToast?.('Bu turda henüz paylaşılmış tur linki yok — yolcular katılamaz', 'warning');
    } catch (e) { showToast?.('❌ Açılamadı: ' + e.message, 'error'); }
  };
  const ask = async (i) => {
    const qs = qsRef.current || [];
    if (!qs[i]) return;
    revealing.current = false;
    await setDoc(doc(db, 'yarisma_oturum', sid), { status: 'q', qIndex: i, q: { text: qs[i].q, o: qs[i].o }, correct: null, qStartedAt: serverTimestamp() }, { merge: true });
  };
  const ranked = [...players].sort((a, b) => (b.score || 0) - (a.score || 0));
  const reveal = async () => {
    if (revealing.current || ses?.status !== 'q') return;
    revealing.current = true;
    if (!qsRef.current) { const g = await getDoc(doc(db, 'yarisma_oturum', sid, 'gizli', 'sorular')).catch(() => null); qsRef.current = g?.exists() ? g.data().questions || [] : []; }
    const i = ses.qIndex, qs = qsRef.current, correct = qs[i]?.a;
    const start = ses.qStartedAt?.toMillis?.() || 0, limitMs = (ses.limit || YARISMA_SURE) * 1000;
    const b = writeBatch(db);
    const next = players.map(p => {
      const an = p.answers?.[i];
      const pts = an && an.c === correct && an.at?.toMillis && start ? yarismaPuan(an.at.toMillis() - start, limitMs) : 0;
      b.update(doc(db, 'yarisma_oturum', sid, 'players', p.id), { score: (p.score || 0) + pts, last: pts });
      return { name: p.name, score: (p.score || 0) + pts };
    }).sort((x, y) => y.score - x.score);
    await b.commit();
    const last = i >= qs.length - 1;
    await setDoc(doc(db, 'yarisma_oturum', sid), { status: last ? 'end' : 'reveal', correct, top: next.slice(0, last ? 10 : 5) }, { merge: true });
  };
  const closeGame = async () => { if (window.confirm('Yarışma kapatılsın mı? Yolcuların ekranından kalkar.')) await setDoc(doc(db, 'yarisma_oturum', sid), { status: 'closed' }, { merge: true }); };

  // Soru açıkken: süre bitince ya da herkes cevaplayınca otomatik cevabı göster
  const i = ses?.qIndex ?? -1;
  const answered = ses?.status === 'q' ? players.filter(p => p.answers?.[i]).length : 0;
  const startMs = ses?.qStartedAt?.toMillis?.();
  const left = ses?.status === 'q' && startMs ? Math.max(0, Math.ceil(((ses.limit || YARISMA_SURE) * 1000 - (now - startMs)) / 1000)) : null;
  useEffect(() => { if (ses?.status === 'q' && ((left === 0) || (players.length && answered === players.length))) reveal(); }, [left, answered, ses?.status]);

  const box = { background: '#0f2137', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '16px', width: '100%', maxWidth: '760px', maxHeight: '92vh', overflow: 'auto', padding: isMobile ? '16px' : '22px', color: '#e8f1f8' };
  const btn = (bg) => ({ padding: '10px 18px', borderRadius: '10px', border: 'none', cursor: 'pointer', fontWeight: 700, fontSize: '14px', color: '#fff', background: bg });
  const inp = { width: '100%', padding: '8px 10px', background: 'rgba(0,0,0,0.25)', border: '1px solid rgba(255,255,255,0.12)', borderRadius: '8px', color: '#e8f1f8', fontSize: '13px', boxSizing: 'border-box' };
  const qs = qsRef.current || [];
  const setQ = (k, patch) => setBank(b => b.map((x, j) => j === k ? { ...x, ...patch } : x));
  return (
    <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', zIndex: 400, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '12px' }}>
      <div onClick={e => e.stopPropagation()} style={box}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '14px' }}>
          <h3 style={{ margin: 0, flex: 1, fontSize: '18px' }}>🏆 Bilgi Yarışması <span style={{ fontSize: '13px', color: '#94a3b8', fontWeight: 400 }}>— {tour.name}</span></h3>
          <button onClick={onClose} style={{ background: 'none', border: 'none', color: '#94a3b8', fontSize: '20px', cursor: 'pointer' }}>✕</button>
        </div>

        {ses === undefined ? <div style={{ color: '#94a3b8' }}>Yükleniyor…</div> : !live ? (
          <>
            <div style={{ fontSize: '13px', color: '#94a3b8', marginBottom: '12px', lineHeight: 1.5 }}>Yarışmayı açınca yolcuların tur linkinde <b>"Canlı yarışma — Katıl"</b> çıkar. Siz soruları buradan tek tek gönderirsiniz; her soru {YARISMA_SURE} saniye. Hızlı ve doğru cevaplayan çok puan alır.</div>
            <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap', marginBottom: '10px' }}>
              {cities.length > 1 && <select value={city} onChange={e => setCity(e.target.value)} style={{ ...inp, width: 'auto' }}>{cities.map(c => <option key={c}>{c}</option>)}</select>}
              <b style={{ fontSize: '14px' }}>📍 {city || '—'} soruları: {bank ? bank.filter(validQ).length : '…'}</b>
              <span style={{ flex: 1 }} />
              <button onClick={genAI} disabled={aiBusy || !city} style={btn('linear-gradient(135deg,#8b5cf6,#6d28d9)')}>{aiBusy ? '⏳ Üretiliyor…' : '🤖 10 soru üret'}</button>
              <button onClick={() => setEdit(e => !e)} style={btn('rgba(255,255,255,0.12)')}>{edit ? 'Listeyi kapat' : '✏️ Soruları düzenle'}</button>
            </div>
            {edit && bank && (
              <div style={{ border: '1px solid rgba(255,255,255,0.08)', borderRadius: '12px', padding: '10px', marginBottom: '12px' }}>
                {bank.map((x, k) => (
                  <div key={k} style={{ padding: '8px 0', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
                    <div style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
                      <b style={{ fontSize: '12px', color: '#64748b', width: '22px' }}>{k + 1}.</b>
                      <input value={x.q} onChange={e => setQ(k, { q: e.target.value })} placeholder="Soru" style={inp} />
                      <button onClick={() => setBank(b => b.filter((_, j) => j !== k))} title="Sil" style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer' }}>🗑</button>
                    </div>
                    <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: '6px', margin: '6px 0 0 28px' }}>
                      {[0, 1, 2, 3].map(o => (
                        <label key={o} style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
                          <input type="radio" checked={x.a === o} onChange={() => setQ(k, { a: o })} title="Doğru cevap" />
                          <input value={x.o?.[o] || ''} onChange={e => { const oo = [...(x.o || ['', '', '', ''])]; oo[o] = e.target.value; setQ(k, { o: oo }); }} placeholder={`Şık ${o + 1}`} style={{ ...inp, borderColor: x.a === o ? '#10b981' : 'rgba(255,255,255,0.12)' }} />
                        </label>
                      ))}
                    </div>
                  </div>
                ))}
                <div style={{ display: 'flex', gap: '8px', marginTop: '10px' }}>
                  <button onClick={() => setBank(b => [...b, { q: '', o: ['', '', '', ''], a: 0 }])} style={btn('rgba(255,255,255,0.12)')}>➕ Soru ekle</button>
                  <span style={{ flex: 1 }} />
                  <button onClick={() => saveBank(bank.filter(validQ))} style={btn('#10b981')}>💾 Kaydet</button>
                </div>
                <div style={{ fontSize: '11px', color: '#64748b', marginTop: '6px' }}>Yuvarlak = doğru cevap. Yapay zekâ sorularını mutlaka kontrol edin; eksik doldurulan soru kaydedilmez.</div>
              </div>
            )}
            <button onClick={openGame} disabled={!bank || !bank.filter(validQ).length} style={{ ...btn('linear-gradient(135deg,#f59e0b,#d97706)'), width: '100%', padding: '14px', fontSize: '16px', opacity: bank && bank.filter(validQ).length ? 1 : 0.5 }}>🏆 Yarışmayı aç ({bank ? bank.filter(validQ).length : 0} soru)</button>
          </>
        ) : (
          <>
            <div style={{ display: 'flex', gap: '10px', alignItems: 'center', marginBottom: '12px', flexWrap: 'wrap' }}>
              <span style={{ padding: '4px 10px', borderRadius: '999px', background: 'rgba(16,185,129,0.15)', color: '#10b981', fontSize: '12px', fontWeight: 700 }}>● CANLI</span>
              <b>{ses.title}</b>
              <span style={{ color: '#94a3b8', fontSize: '13px' }}>👥 {players.length} oyuncu</span>
              <span style={{ flex: 1 }} />
              <button onClick={closeGame} style={btn('rgba(239,68,68,0.25)')}>Yarışmayı kapat</button>
            </div>
            {ses.status === 'lobby' && (
              <div>
                <div style={{ fontSize: '13px', color: '#94a3b8', marginBottom: '8px' }}>Yolcular tur linkinden katılıyor. Herkes gelince başlatın.</div>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px', minHeight: '40px', marginBottom: '14px' }}>
                  {players.map(p => <span key={p.id} style={{ padding: '6px 12px', borderRadius: '999px', background: 'rgba(59,130,246,0.15)', fontSize: '13px' }}>{p.name}</span>)}
                  {!players.length && <span style={{ color: '#64748b', fontSize: '13px' }}>Henüz katılan yok…</span>}
                </div>
                <button onClick={() => ask(0)} disabled={!qs.length} style={{ ...btn('#10b981'), width: '100%', padding: '14px', fontSize: '16px' }}>▶ 1. soruyu gönder</button>
              </div>
            )}
            {(ses.status === 'q' || ses.status === 'reveal') && ses.q && (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '13px', color: '#94a3b8', marginBottom: '6px' }}>
                  <span>Soru {i + 1} / {ses.total}</span>
                  {ses.status === 'q' ? <span>⏱ <b style={{ color: '#fbbf24', fontSize: '16px' }}>{left ?? '…'}</b> sn · ✋ {answered}/{players.length} cevapladı</span> : <span>✅ Cevap gösterildi</span>}
                </div>
                <div style={{ fontSize: '18px', fontWeight: 700, margin: '6px 0 12px' }}>{ses.q.text}</div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px', marginBottom: '14px' }}>
                  {ses.q.o.map((o, k) => {
                    const n = players.filter(p => p.answers?.[i]?.c === k).length;
                    const ok = ses.status === 'reveal' && ses.correct === k;
                    return <div key={k} style={{ padding: '12px', borderRadius: '10px', background: ses.status === 'reveal' ? (ok ? '#10b981' : 'rgba(255,255,255,0.05)') : SIK_RENK[k], fontWeight: 600, fontSize: '14px', display: 'flex', justifyContent: 'space-between' }}><span>{ok ? '✓ ' : ''}{o}</span>{ses.status === 'reveal' && <span>{n}</span>}</div>;
                  })}
                </div>
                {ses.status === 'q'
                  ? <button onClick={reveal} style={{ ...btn('#3b82f6'), width: '100%' }}>Cevabı şimdi göster</button>
                  : <button onClick={() => ask(i + 1)} style={{ ...btn('#10b981'), width: '100%', padding: '14px', fontSize: '16px' }}>▶ {i + 2}. soruyu gönder</button>}
              </div>
            )}
            {(ses.status === 'reveal' || ses.status === 'end') && (
              <div style={{ marginTop: '14px' }}>
                <div style={{ fontSize: '12px', color: '#94a3b8', fontWeight: 700, marginBottom: '6px' }}>{ses.status === 'end' ? '🏁 SONUÇ' : 'SIRALAMA'}</div>
                {ranked.slice(0, ses.status === 'end' ? 10 : 5).map((p, k) => (
                  <div key={p.id} style={{ display: 'flex', gap: '10px', padding: '8px 10px', borderRadius: '8px', background: k === 0 ? 'rgba(245,158,11,0.15)' : 'transparent', fontSize: '14px' }}>
                    <b style={{ width: '28px' }}>{['🥇', '🥈', '🥉'][k] || k + 1 + '.'}</b><span style={{ flex: 1 }}>{p.name}</span>
                    {ses.status === 'reveal' && p.last ? <span style={{ color: '#10b981', fontSize: '12px' }}>+{p.last}</span> : null}<b>{p.score || 0}</b>
                  </div>
                ))}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

// ===== 📢 Duyurular: müşteri ve tur linklerinde görünen görselli pano =====
// Firestore duyurular/<id> (herkes okur, CRM yazar) · görsel Storage duyurular/<id>.jpg (1600px'e küçültülür).
// Hedef: tüm linkler / sadece tur linkleri / sadece müşteri linkleri / tek bir tur. Tarih aralığı dışında görünmez.
const DUYURU_HEDEF = [['all', 'Tüm linkler'], ['tour', 'Sadece tur linkleri'], ['customer', 'Sadece müşteri linkleri'], ['onetour', 'Belirli bir tur']];
const shrinkImage = (file, max = 1600) => new Promise((ok, no) => {
  const img = new Image(), url = URL.createObjectURL(file);
  img.onload = () => {
    const k = Math.min(1, max / Math.max(img.width, img.height));
    const c = document.createElement('canvas'); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
    c.getContext('2d').drawImage(img, 0, 0, c.width, c.height); URL.revokeObjectURL(url);
    c.toBlob(b => b ? ok(b) : no(new Error('görsel işlenemedi')), 'image/jpeg', 0.85);
  };
  img.onerror = () => { URL.revokeObjectURL(url); no(new Error('görsel açılamadı')); };
  img.src = url;
});
// scope: 'customer' (müşteri linkleri) · 'tours' (tüm tur linkleri) · 'onetour' (fixedTour) · yoksa hepsi
function DuyurularModule({ tours = [], showToast, isMobile, currentUser, scope, fixedTour, embedded }) {
  const defTarget = scope === 'customer' ? 'customer' : scope === 'tours' ? 'tour' : scope === 'onetour' ? 'onetour' : 'all';
  const empty = { title: '', text: '', link: '', target: defTarget, tourId: fixedTour ? String(fixedTour.id) : '', start: '', end: '', active: true };
  const inScope = (d) => !scope || (scope === 'customer' ? ['customer', 'all'].includes(d.target) : scope === 'tours' ? ['tour', 'all'].includes(d.target) : d.target === 'onetour' && String(d.tourId) === String(fixedTour?.id));
  const [list, setList] = useState(null);
  const [form, setForm] = useState(null); // düzenlenen duyuru
  const [file, setFile] = useState(null);
  const [preview, setPreview] = useState('');
  const [busy, setBusy] = useState(false);
  const [drag, setDrag] = useState(false);
  const load = () => getDocs(collection(db, 'duyurular')).then(q => setList(q.docs.map(d => ({ id: d.id, ...d.data() })).filter(inScope).sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))))).catch(e => { setList([]); showToast?.('Duyurular okunamadı: ' + e.message, 'error'); });
  useEffect(() => { load(); }, [scope, fixedTour?.id]);
  const pick = (f) => { if (!f || !/^image\//.test(f.type)) { showToast?.('Görsel dosyası seçin (JPG, PNG)', 'warning'); return; } setFile(f); setPreview(URL.createObjectURL(f)); };
  const upd = (p) => setForm(f => ({ ...f, ...p }));
  const save = async () => {
    if (!form.title.trim() && !file && !form.image) { showToast?.('Başlık ya da görsel ekleyin', 'warning'); return; }
    if (form.link && !/^https:\/\//.test(form.link.trim())) { showToast?.('Bağlantı https:// ile başlamalı', 'warning'); return; }
    if (form.target === 'onetour' && !form.tourId) { showToast?.('Turu seçin', 'warning'); return; }
    setBusy(true);
    try {
      const id = form.id || generateUniqueId();
      let image = form.image || '', imagePath = form.imagePath || '';
      if (file) {
        const { getStorage, ref, uploadBytes, getDownloadURL } = await import('firebase/storage');
        imagePath = `duyurular/${id}-${Date.now()}.jpg`;
        const r = ref(getStorage(), imagePath);
        await uploadBytes(r, await shrinkImage(file), { contentType: 'image/jpeg' });
        image = await getDownloadURL(r);
      }
      const tour = form.target === 'onetour' ? (tours.find(t => String(t.id) === String(form.tourId)) || (fixedTour && String(fixedTour.id) === String(form.tourId) ? fixedTour : null)) : null;
      await setDoc(doc(db, 'duyurular', id), {
        title: form.title.trim(), text: form.text.trim(), link: form.link.trim(), image, imagePath,
        target: form.target, tourId: tour ? String(tour.id) : '', tourName: tour?.name || '',
        start: form.start || '', end: form.end || '', active: !!form.active,
        createdAt: form.createdAt || new Date().toISOString(), updatedAt: new Date().toISOString(), by: currentUser?.name || '',
      });
      // Tek tur hedefinde eski tur linklerine tur kimliği yaz (sayfa duyuruyu bununla eşleştirir)
      if (tour) await Promise.all((tour.reservations || []).filter(r => !r.cancelled && r.shareToken).map(r => setDoc(doc(db, 'paylasimlar', r.shareToken), { tourId: String(tour.id) }, { merge: true }).catch(() => {})));
      // Görsel değiştiyse eskisini sil
      if (file && form.imagePath && form.imagePath !== imagePath) { try { const { getStorage, ref, deleteObject } = await import('firebase/storage'); await deleteObject(ref(getStorage(), form.imagePath)); } catch (e) { /* yok */ } }
      const where = form.target === 'customer' ? 'müşteri linklerine' : form.target === 'all' ? 'müşteri ve tur linklerine' : tour ? `${tour.name} tur linklerine` : 'bütün tur linklerine';
      showToast?.(`📢 Duyuru ${where} gönderildi`, 'success');
      setForm(null); setFile(null); setPreview(''); load();
    } catch (e) { showToast?.('❌ Kaydedilemedi: ' + e.message, 'error'); }
    setBusy(false);
  };
  const toggle = async (d) => { await setDoc(doc(db, 'duyurular', d.id), { active: !d.active }, { merge: true }); load(); };
  const remove = async (d) => {
    if (!window.confirm(`"${d.title || 'Duyuru'}" silinsin mi? Linklerden hemen kalkar.`)) return;
    await deleteDoc(doc(db, 'duyurular', d.id));
    if (d.imagePath) { try { const { getStorage, ref, deleteObject } = await import('firebase/storage'); await deleteObject(ref(getStorage(), d.imagePath)); } catch (e) { /* yok */ } }
    load();
  };
  const today = new Date().toISOString().slice(0, 10);
  const stateOf = (d) => !d.active ? ['Kapalı', '#64748b'] : d.start && d.start > today ? ['Planlı', '#f59e0b'] : d.end && d.end < today ? ['Süresi bitti', '#64748b'] : ['Yayında', '#10b981'];
  const inp = { width: '100%', padding: '10px 12px', background: 'rgba(0,0,0,0.25)', border: '1px solid rgba(255,255,255,0.12)', borderRadius: '8px', color: '#e8f1f8', fontSize: '14px', boxSizing: 'border-box' };
  const lbl = { display: 'block', fontSize: '12px', color: '#94a3b8', margin: '12px 0 6px', fontWeight: 600 };
  const card = { background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: '14px', padding: isMobile ? '14px' : '18px' };
  const activeTours = tours.filter(t => !t.endDate || t.endDate >= today).sort((a, b) => String(a.startDate).localeCompare(String(b.startDate)));
  const img = preview || form?.image;
  return (
    <div style={{ padding: embedded ? 0 : isMobile ? '16px' : '24px', maxWidth: '1100px' }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '6px', flexWrap: 'wrap' }}>
        {embedded ? <h3 style={{ fontSize: '16px', margin: 0, flex: 1 }}>📢 Duyurular</h3> : <h2 style={{ fontSize: '20px', margin: 0, flex: 1 }}>📢 Duyurular</h2>}
        {!form && <button onClick={() => { setForm({ ...empty }); setFile(null); setPreview(''); }} style={{ padding: '10px 18px', borderRadius: '10px', border: 'none', cursor: 'pointer', fontWeight: 700, color: '#fff', background: 'linear-gradient(135deg,#3b82f6,#2563eb)' }}>➕ Yeni duyuru</button>}
      </div>
      {!embedded && <p style={{ margin: '0 0 18px', fontSize: '13px', color: '#64748b' }}>Görsel yüklerseniz linkte sadece görsel (afiş) görünür, dokununca bağlantı açılır. Görsel yoksa başlık + metin "Ana ekrana ekleyin" kartı gibi görünür. Kaydedince linkler bir sonraki açılışta günceldir.</p>}
      {embedded && <div style={{ height: '12px' }} />}
      {form && (
        <div style={{ ...card, marginBottom: '18px', display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '1fr 1fr', gap: '18px' }}>
          <div>
            <label onDragOver={e => { e.preventDefault(); setDrag(true); }} onDragLeave={() => setDrag(false)} onDrop={e => { e.preventDefault(); setDrag(false); pick(e.dataTransfer.files?.[0]); }}
              style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '8px', minHeight: '220px', borderRadius: '12px', border: `2px dashed ${drag ? '#3b82f6' : 'rgba(255,255,255,0.18)'}`, background: drag ? 'rgba(59,130,246,0.08)' : 'rgba(0,0,0,0.2)', cursor: 'pointer', overflow: 'hidden' }}>
              <input type="file" accept="image/*" style={{ display: 'none' }} onChange={e => { pick(e.target.files?.[0]); e.target.value = ''; }} />
              {img ? <img src={img} alt="" style={{ width: '100%', maxHeight: '360px', objectFit: 'contain' }} />
                : <><span style={{ fontSize: '40px' }}>🖼️</span><b style={{ fontSize: '14px' }}>Görseli sürükleyin ya da tıklayın</b><span style={{ fontSize: '12px', color: '#64748b' }}>Afiş, kampanya görseli… (otomatik küçültülür)</span></>}
            </label>
            {img && <button onClick={() => { setFile(null); setPreview(''); upd({ image: '', imagePath: form.imagePath }); }} style={{ marginTop: '6px', background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', fontSize: '12px' }}>Görseli kaldır</button>}
          </div>
          <div>
            <label style={{ ...lbl, marginTop: 0 }}>Başlık</label>
            <input value={form.title} maxLength={80} onChange={e => upd({ title: e.target.value })} placeholder="Kapadokya balon turu — erken rezervasyon" style={inp} />
            <label style={lbl}>Metin <span style={{ color: '#64748b', fontWeight: 400 }}>(isteğe bağlı)</span></label>
            <textarea value={form.text} maxLength={400} rows={3} onChange={e => upd({ text: e.target.value })} style={{ ...inp, resize: 'vertical', fontFamily: 'inherit' }} />
            <label style={lbl}>Bağlantı <span style={{ color: '#64748b', fontWeight: 400 }}>(isteğe bağlı — kartta "Aç" butonu)</span></label>
            <input value={form.link} onChange={e => upd({ link: e.target.value })} placeholder="https://paydostur.com/..." style={inp} />
            {/* Hangi linke gidecek: müşteri linki / tur linki (tüm turlar ya da tek tur) / ikisi de */}
            <label style={lbl}>Hangi linke gidecek?</label>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '6px' }}>
              {[['customer', '📱 Müşteri linki'], ['tour', '🎫 Tur linki'], ['all', '📱+🎫 İkisine de']].map(([k, t]) => {
                const on = k === 'tour' ? ['tour', 'onetour'].includes(form.target) : form.target === k;
                return <button key={k} type="button" onClick={() => upd(k === 'tour' ? { target: form.tourId ? 'onetour' : 'tour' } : { target: k })} style={{ padding: '10px 6px', borderRadius: '10px', cursor: 'pointer', fontWeight: 700, fontSize: '12.5px', color: on ? '#fff' : '#94a3b8', background: on ? 'rgba(59,130,246,0.25)' : 'rgba(0,0,0,0.2)', border: `1px solid ${on ? '#3b82f6' : 'rgba(255,255,255,0.12)'}` }}>{t}</button>;
              })}
            </div>
            {['tour', 'onetour'].includes(form.target) && (
              <select value={form.target === 'onetour' ? form.tourId : ''} onChange={e => upd(e.target.value ? { target: 'onetour', tourId: e.target.value } : { target: 'tour', tourId: '' })} style={{ ...inp, marginTop: '8px' }}>
                <option value="">🌐 Bütün turların linklerine</option>
                {(fixedTour && !activeTours.some(t => String(t.id) === String(fixedTour.id)) ? [fixedTour, ...activeTours] : activeTours).map(t => <option key={t.id} value={String(t.id)}>{t.name} · {formatDate(t.startDate)}</option>)}
              </select>
            )}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px' }}>
              <div><label style={lbl}>Başlangıç</label><input type="date" value={form.start} onChange={e => upd({ start: e.target.value })} style={inp} /></div>
              <div><label style={lbl}>Bitiş</label><input type="date" value={form.end} onChange={e => upd({ end: e.target.value })} style={inp} /></div>
            </div>
            <label style={{ display: 'flex', gap: '8px', alignItems: 'center', marginTop: '12px', fontSize: '13px' }}><input type="checkbox" checked={form.active} onChange={e => upd({ active: e.target.checked })} /> Yayında</label>
            <div style={{ display: 'flex', gap: '8px', marginTop: '16px' }}>
              <button onClick={save} disabled={busy} style={{ flex: 1, padding: '12px', borderRadius: '10px', border: 'none', cursor: busy ? 'wait' : 'pointer', fontWeight: 700, color: '#fff', background: '#10b981', opacity: busy ? 0.6 : 1 }}>{busy ? 'Kaydediliyor…' : '💾 Kaydet'}</button>
              <button onClick={() => { setForm(null); setFile(null); setPreview(''); }} style={{ padding: '12px 18px', borderRadius: '10px', border: '1px solid rgba(255,255,255,0.15)', background: 'none', color: '#e8f1f8', cursor: 'pointer' }}>Vazgeç</button>
            </div>
          </div>
        </div>
      )}
      {list === null ? <div style={{ color: '#64748b' }}>Yükleniyor…</div> : !list.length ? <div style={{ ...card, color: '#64748b', fontSize: '13px' }}>Henüz duyuru yok.</div> : (
        <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : 'repeat(3, 1fr)', gap: '12px', alignItems: 'start' }}>
          {list.map(d => { const [st, sc] = stateOf(d); return (
            <div key={d.id} style={{ ...card, padding: 0, overflow: 'hidden', opacity: st === 'Yayında' ? 1 : 0.7 }}>
              {d.image && <img src={d.image} alt="" style={{ width: '100%', height: '160px', objectFit: 'cover', display: 'block' }} />}
              <div style={{ padding: '12px 14px' }}>
                <div style={{ display: 'flex', gap: '6px', alignItems: 'center', marginBottom: '4px' }}>
                  <span style={{ fontSize: '11px', fontWeight: 700, color: sc }}>● {st}</span>
                  <span style={{ fontSize: '11px', color: '#64748b' }}>· {d.target === 'onetour' ? d.tourName || 'Tek tur' : (DUYURU_HEDEF.find(x => x[0] === d.target) || [])[1]}</span>
                </div>
                <b style={{ fontSize: '14px' }}>{d.title || '(başlıksız)'}</b>
                {(d.start || d.end) && <div style={{ fontSize: '11px', color: '#64748b', marginTop: '2px' }}>{d.start ? formatDate(d.start) : '…'} → {d.end ? formatDate(d.end) : '…'}</div>}
                <div style={{ display: 'flex', gap: '6px', marginTop: '10px' }}>
                  <button onClick={() => { setForm({ ...empty, ...d }); setFile(null); setPreview(''); window.scrollTo({ top: 0, behavior: 'smooth' }); }} style={{ flex: 1, padding: '7px', borderRadius: '8px', border: '1px solid rgba(255,255,255,0.15)', background: 'none', color: '#e8f1f8', cursor: 'pointer', fontSize: '12px' }}>✏️ Düzenle</button>
                  <button onClick={() => toggle(d)} style={{ flex: 1, padding: '7px', borderRadius: '8px', border: '1px solid rgba(255,255,255,0.15)', background: 'none', color: '#e8f1f8', cursor: 'pointer', fontSize: '12px' }}>{d.active ? '⏸ Kapat' : '▶ Yayınla'}</button>
                  <button onClick={() => remove(d)} style={{ padding: '7px 10px', borderRadius: '8px', border: '1px solid rgba(239,68,68,0.35)', background: 'none', color: '#ef4444', cursor: 'pointer', fontSize: '12px' }}>🗑</button>
                </div>
              </div>
            </div>); })}
        </div>
      )}
    </div>
  );
}

// ===== 📱 Müşteri Linki (sol menü): tüm müşteri linkleri için duyuru + bildirim =====
function MusteriLinkiModule({ customers, tours, showToast, isMobile, currentUser, bare }) {
  const [tab, setTab] = useState('duyuru');
  const tb = (k, t) => <button onClick={() => setTab(k)} style={{ padding: '9px 16px', borderRadius: '10px', cursor: 'pointer', fontWeight: 700, fontSize: '13px', color: tab === k ? '#fff' : '#94a3b8', background: tab === k ? 'rgba(59,130,246,0.25)' : 'transparent', border: `1px solid ${tab === k ? '#3b82f6' : 'rgba(255,255,255,0.1)'}` }}>{t}</button>;
  return (
    <div>
      <div style={{ padding: bare ? (isMobile ? '0 16px' : '0 24px') : isMobile ? '16px 16px 0' : '24px 24px 0' }}>
        {!bare && <h2 style={{ fontSize: '20px', margin: '0 0 4px' }}>📱 Müşteri Linki</h2>}
        <p style={{ margin: '0 0 14px', fontSize: '13px', color: '#64748b' }}>Bütün müşteri linklerinde (/m/) görünenler. Tek müşterinin belgeleri için müşteri kartındaki "Müşteri Linki" butonunu kullanın.</p>
        <div style={{ display: 'flex', gap: '8px' }}>{tb('duyuru', '📢 Duyurular')}{tb('bildirim', '📣 Bildirimler')}</div>
      </div>
      {tab === 'duyuru'
        ? <div style={{ padding: isMobile ? '16px' : '20px 24px' }}><DuyurularModule scope="customer" embedded tours={tours} showToast={showToast} isMobile={isMobile} currentUser={currentUser} /></div>
        : <BildirimlerModule customers={customers} showToast={showToast} isMobile={isMobile} />}
    </div>
  );
}

// ===== 🎫 Tur Linki (sol menü): tur seçilir → o turun duyuruları, yarışma, tavsiyeler, link durumu =====
function TurLinkiModule({ tours = [], showToast, isMobile, currentUser, bare }) {
  const today = new Date().toISOString().slice(0, 10);
  const [sel, setSel] = useState('');
  const [q, setQ] = useState('');
  const [showOld, setShowOld] = useState(false);
  const [yarisma, setYarisma] = useState(false);
  const [tavsiye, setTavsiye] = useState(false);
  const list = tours.filter(t => showOld || !t.endDate || t.endDate >= today)
    .filter(t => !q || `${t.name} ${t.city} ${t.country}`.toLocaleLowerCase('tr').includes(q.toLocaleLowerCase('tr')))
    .sort((a, b) => String(a.startDate).localeCompare(String(b.startDate)));
  const tour = sel && sel !== 'all' ? tours.find(t => String(t.id) === sel) : null;
  const res = tour ? (tour.reservations || []).filter(r => !r.cancelled) : [];
  const shared = res.filter(r => r.shareToken).length;
  const item = (key, title, sub, on) => (
    <button key={key} onClick={() => setSel(key)} style={{ width: '100%', textAlign: 'left', padding: '10px 12px', borderRadius: '10px', cursor: 'pointer', color: '#e8f1f8', background: on ? 'rgba(245,158,11,0.15)' : 'transparent', border: `1px solid ${on ? 'rgba(245,158,11,0.5)' : 'rgba(255,255,255,0.06)'}`, marginBottom: '6px' }}>
      <div style={{ fontWeight: 700, fontSize: '13px' }}>{title}</div><div style={{ fontSize: '11.5px', color: '#94a3b8' }}>{sub}</div>
    </button>
  );
  const btn = (bg, bc, c) => ({ padding: '10px 16px', borderRadius: '10px', cursor: 'pointer', fontWeight: 700, fontSize: '13px', background: bg, border: `1px solid ${bc}`, color: c });
  return (
    <div style={{ padding: bare ? (isMobile ? '0 16px 16px' : '0 24px 24px') : isMobile ? '16px' : '24px' }}>
      {!bare && <h2 style={{ fontSize: '20px', margin: '0 0 4px' }}>🎫 Tur Linki</h2>}
      <p style={{ margin: '0 0 16px', fontSize: '13px', color: '#64748b' }}>Tur seçin: o turun yolcularının linkinde (/b/) görünecek duyurular, canlı yarışma ve şehir tavsiyeleri.</p>
      <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '280px 1fr', gap: '16px', alignItems: 'start' }}>
        <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: '14px', padding: '12px', maxHeight: isMobile ? '260px' : '75vh', overflow: 'auto' }}>
          <input value={q} onChange={e => setQ(e.target.value)} placeholder="Tur ara…" style={{ width: '100%', padding: '8px 10px', marginBottom: '8px', background: 'rgba(0,0,0,0.25)', border: '1px solid rgba(255,255,255,0.12)', borderRadius: '8px', color: '#e8f1f8', fontSize: '13px', boxSizing: 'border-box' }} />
          {item('all', '🌐 Tüm tur linkleri', 'Her turda görünecek duyurular', sel === 'all')}
          {list.map(t => item(String(t.id), t.name, `${t.city || t.country || ''} · ${formatDate(t.startDate)}${t.startDate <= today && (!t.endDate || t.endDate >= today) ? ' · 🟢 devam ediyor' : ''}`, sel === String(t.id)))}
          {!list.length && <div style={{ fontSize: '12px', color: '#64748b', padding: '6px' }}>Tur yok.</div>}
          <label style={{ display: 'flex', gap: '6px', alignItems: 'center', fontSize: '12px', color: '#94a3b8', marginTop: '6px' }}><input type="checkbox" checked={showOld} onChange={e => setShowOld(e.target.checked)} /> Biten turları da göster</label>
        </div>
        <div>
          {!sel && <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px dashed rgba(255,255,255,0.12)', borderRadius: '14px', padding: '40px 20px', textAlign: 'center', color: '#64748b', fontSize: '14px' }}>{isMobile ? '↑ Yukarıdan' : '← Soldan'} bir tur seçin</div>}
          {sel === 'all' && <DuyurularModule key="all" scope="tours" embedded tours={tours} showToast={showToast} isMobile={isMobile} currentUser={currentUser} />}
          {tour && (
            <>
              <div style={{ background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: '14px', padding: '16px', marginBottom: '16px' }}>
                <div style={{ fontSize: '17px', fontWeight: 700 }}>{tour.name}</div>
                <div style={{ fontSize: '12.5px', color: '#94a3b8', margin: '2px 0 12px' }}>🌍 {tour.country}{tour.city ? ` — ${tour.city}` : ''} · 📅 {formatDate(tour.startDate)} → {formatDate(tour.endDate)} · 🔗 {shared}/{res.length} yolcuya link gönderildi</div>
                <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                  <button onClick={() => setYarisma(true)} style={btn('rgba(245,158,11,0.15)', 'rgba(245,158,11,0.45)', '#fbbf24')}>🏆 Canlı yarışma</button>
                  <button onClick={() => setTavsiye(true)} style={btn('rgba(249,115,22,0.12)', 'rgba(249,115,22,0.4)', '#fb923c')}>⭐ {tour.city || 'Şehir'} tavsiyeleri</button>
                </div>
                {shared < res.length && <div style={{ fontSize: '12px', color: '#fbbf24', marginTop: '10px' }}>{res.length - shared} yolcuya henüz tur linki gönderilmedi (Turlar → bu tur → yolcunun 🔗 butonu).</div>}
              </div>
              <DuyurularModule key={tour.id} scope="onetour" fixedTour={tour} embedded tours={tours} showToast={showToast} isMobile={isMobile} currentUser={currentUser} />
              {yarisma && <YarismaModal tour={tour} onClose={() => setYarisma(false)} showToast={showToast} isMobile={isMobile} />}
              {tavsiye && <TavsiyelerModal focusCity={tour.city || ''} onClose={() => setTavsiye(false)} showToast={showToast} isMobile={isMobile} currentUser={currentUser} />}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

// ===== 📢 Duyurular (sol menü, tek bölüm): içinde iki sekme — Müşteri Linki | Tur Linki =====
function LinkDuyuruModule({ customers, tours, showToast, isMobile, currentUser }) {
  const [tab, setTab] = useState(() => { try { return localStorage.getItem('paydos_duyuru_tab') || 'musteri'; } catch (e) { return 'musteri'; } });
  const go = (k) => { setTab(k); try { localStorage.setItem('paydos_duyuru_tab', k); } catch (e) { /* yok */ } };
  const tb = (k, t) => <button onClick={() => go(k)} style={{ flex: isMobile ? 1 : 'none', padding: '11px 20px', cursor: 'pointer', fontWeight: 700, fontSize: '14px', background: 'none', border: 'none', borderBottom: `3px solid ${tab === k ? '#f59e0b' : 'transparent'}`, color: tab === k ? '#fff' : '#94a3b8' }}>{t}</button>;
  return (
    <div>
      <div style={{ padding: isMobile ? '16px 16px 0' : '24px 24px 0' }}>
        <h2 style={{ fontSize: '20px', margin: '0 0 10px' }}>📢 Duyurular</h2>
        <div style={{ display: 'flex', gap: '4px', borderBottom: '1px solid rgba(255,255,255,0.1)', marginBottom: '16px' }}>{tb('musteri', '📱 Müşteri Linki')}{tb('tur', '🎫 Tur Linki')}</div>
      </div>
      {tab === 'musteri'
        ? <MusteriLinkiModule bare customers={customers} tours={tours} showToast={showToast} isMobile={isMobile} currentUser={currentUser} />
        : <TurLinkiModule bare tours={tours} showToast={showToast} isMobile={isMobile} currentUser={currentUser} />}
    </div>
  );
}

function TavsiyelerModal({ onClose, showToast, isMobile, currentUser, focusCity, asPage }) {
  const [cities, setCities] = useState(null); // [{ key, city, country, restaurants, dirty }]
  const [sel, setSel] = useState('');
  const [busy, setBusy] = useState(false);
  const [newCity, setNewCity] = useState({ city: '', country: '' });
  useEffect(() => {
    getDocs(collection(db, 'tavsiyeler')).then(snap => {
      const list = snap.docs.map(d => ({ key: d.id, city: d.data().city || d.id, country: d.data().country || '', restaurants: Array.isArray(d.data().restaurants) ? d.data().restaurants : [], dirty: false }))
        .sort((a, b) => a.city.localeCompare(b.city, 'tr'));
      setCities(list);
      const fk = tourCities(focusCity).map(cityKey)[0];
      if (fk && list.some(c => c.key === fk)) setSel(fk);
      else if (focusCity && tourCities(focusCity)[0]) setNewCity({ city: tourCities(focusCity)[0], country: '' });
      if (!fk || !list.some(c => c.key === fk)) setSel(list[0]?.key || '');
    }).catch(e => { setCities([]); showToast?.('Tavsiyeler okunamadı: ' + e.message, 'error'); });
  }, []);
  const cur = (cities || []).find(c => c.key === sel);
  const patchCur = (fn) => setCities(cs => cs.map(c => c.key === sel ? { ...fn(c), dirty: true } : c));
  const updR = (i, f, v) => patchCur(c => ({ ...c, restaurants: c.restaurants.map((r, j) => j === i ? { ...r, [f]: v } : r) }));
  const moveR = (i, d) => patchCur(c => { const n = [...c.restaurants]; const j = i + d; if (j < 0 || j >= n.length) return c; [n[i], n[j]] = [n[j], n[i]]; return { ...c, restaurants: n }; });
  const addCity = () => {
    const name = newCity.city.trim(); const key = cityKey(name);
    if (!key) { showToast?.('Şehir adı girin', 'warning'); return; }
    if ((cities || []).some(c => c.key === key)) { setSel(key); showToast?.('Bu şehir zaten var', 'info'); return; }
    setCities(cs => [...cs, { key, city: titleCaseTr(name), country: newCity.country.trim(), restaurants: [{ ...EMPTY_REST }], dirty: true }].sort((a, b) => a.city.localeCompare(b.city, 'tr')));
    setSel(key); setNewCity({ city: '', country: '' });
  };
  const save = async () => {
    if (!cur) return;
    const restaurants = cur.restaurants.map(r => ({ name: String(r.name || '').trim(), cuisine: String(r.cuisine || '').trim(), price: String(r.price || ''), note: String(r.note || '').trim(), address: String(r.address || '').trim() })).filter(r => r.name);
    setBusy(true);
    try {
      await setDoc(doc(db, 'tavsiyeler', cur.key), { city: cur.city, country: cur.country || '', restaurants, updatedAt: new Date().toISOString(), updatedBy: currentUser?.name || '' });
      setCities(cs => cs.map(c => c.key === cur.key ? { ...c, restaurants, dirty: false } : c));
      showToast?.(`${cur.city} kaydedildi — bu şehre giden tur linklerinde hemen görünür`, 'success');
    } catch (e) { showToast?.('Kaydedilemedi: ' + e.message, 'error'); }
    finally { setBusy(false); }
  };
  const removeCity = async () => {
    if (!cur || !window.confirm(`${cur.city} ve tüm tavsiyeleri silinsin mi?`)) return;
    try { await deleteDoc(doc(db, 'tavsiyeler', cur.key)); } catch (e) { showToast?.('Silinemedi: ' + e.message, 'error'); return; }
    const rest = cities.filter(c => c.key !== cur.key); setCities(rest); setSel(rest[0]?.key || '');
  };
  const close = () => { if (asPage) return; if ((cities || []).some(c => c.dirty) && !window.confirm('Kaydedilmemiş değişiklik var. Kapatılsın mı?')) return; onClose(); };
  // Sayfa modunda (sol menü) başka modüle geçerken kaydedilmemiş değişiklik uyarısı
  useEffect(() => {
    if (!asPage) return;
    const h = (e) => { if ((cities || []).some(c => c.dirty)) { e.preventDefault(); e.returnValue = ''; } };
    window.addEventListener('beforeunload', h); return () => window.removeEventListener('beforeunload', h);
  }, [asPage, cities]);
  const fs = { padding: '8px 10px', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.12)', borderRadius: '8px', color: '#fff', fontSize: '13px', width: '100%', boxSizing: 'border-box' };
  const small = { padding: '6px 9px', background: 'rgba(255,255,255,0.06)', border: 'none', borderRadius: '6px', color: '#94a3b8', cursor: 'pointer' };
  return (
    <div style={asPage ? { padding: isMobile ? '12px' : '24px' } : { position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.65)', zIndex: 3000, display: 'flex', alignItems: isMobile ? 'stretch' : 'center', justifyContent: 'center', padding: isMobile ? 0 : '20px' }} onClick={close}>
      <div onClick={e => e.stopPropagation()} style={{ background: '#0f2744', border: '1px solid rgba(249,115,22,0.35)', borderRadius: isMobile && !asPage ? 0 : '16px', width: '100%', maxWidth: asPage ? '1100px' : '980px', margin: asPage ? '0 auto' : undefined, maxHeight: asPage ? (isMobile ? 'none' : 'calc(100vh - 48px)') : isMobile ? '100vh' : '88vh', minHeight: asPage && !isMobile ? '70vh' : undefined, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '16px 18px', borderBottom: '1px solid rgba(255,255,255,0.08)' }}>
          <div>
            <h3 style={{ margin: 0, fontSize: '17px' }}>⭐ Tavsiyeler</h3>
            <p style={{ margin: '3px 0 0', fontSize: '11px', color: '#94a3b8' }}>Şehir bazlı tavsiye restoranlar. Turun şehriyle eşleşen tavsiyeler o turun linkinde otomatik görünür.</p>
          </div>
          {!asPage && <button onClick={close} style={{ background: 'none', border: 'none', color: '#94a3b8', fontSize: '20px', cursor: 'pointer' }}>✕</button>}
        </div>
        {cities === null ? <div style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>⏳ Yükleniyor...</div> : (
          <div style={{ display: 'flex', flexDirection: isMobile ? 'column' : 'row', flex: 1, minHeight: 0 }}>
            {/* Şehirler */}
            <div style={{ width: isMobile ? 'auto' : '250px', borderRight: isMobile ? 'none' : '1px solid rgba(255,255,255,0.08)', borderBottom: isMobile ? '1px solid rgba(255,255,255,0.08)' : 'none', padding: '12px', overflowY: 'auto', flexShrink: 0, maxHeight: isMobile ? '34vh' : 'none' }}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', marginBottom: '10px' }}>
                <input value={newCity.city} onChange={e => setNewCity({ ...newCity, city: e.target.value })} onKeyDown={e => e.key === 'Enter' && addCity()} placeholder="Şehir (ör. Bakü)" style={fs} />
                <input value={newCity.country} onChange={e => setNewCity({ ...newCity, country: e.target.value })} onKeyDown={e => e.key === 'Enter' && addCity()} placeholder="Ülke (isteğe bağlı)" style={fs} />
                <button onClick={addCity} style={{ padding: '8px', background: 'rgba(249,115,22,0.18)', border: '1px solid rgba(249,115,22,0.4)', borderRadius: '8px', color: '#fb923c', cursor: 'pointer', fontSize: '12px', fontWeight: '600' }}>+ Şehir ekle</button>
              </div>
              {cities.length === 0 && <div style={{ fontSize: '12px', color: '#64748b', padding: '6px' }}>Henüz şehir yok.</div>}
              {cities.map(c => (
                <button key={c.key} onClick={() => setSel(c.key)} style={{ display: 'flex', width: '100%', justifyContent: 'space-between', alignItems: 'center', gap: '6px', padding: '9px 10px', marginBottom: '4px', background: sel === c.key ? 'rgba(249,115,22,0.18)' : 'transparent', border: sel === c.key ? '1px solid rgba(249,115,22,0.4)' : '1px solid transparent', borderRadius: '8px', color: sel === c.key ? '#fb923c' : '#e8f1f8', cursor: 'pointer', fontSize: '13px', textAlign: 'left' }}>
                  <span>{c.city}{c.country ? <span style={{ color: '#64748b', fontSize: '11px' }}> · {c.country}</span> : ''}{c.dirty ? ' •' : ''}</span>
                  <span style={{ fontSize: '11px', color: '#94a3b8' }}>{c.restaurants.filter(r => String(r.name || '').trim()).length} 🍽️</span>
                </button>
              ))}
            </div>
            {/* Seçili şehrin restoranları */}
            <div style={{ flex: 1, padding: '14px', overflowY: 'auto', minHeight: 0 }}>
              {!cur ? <div style={{ color: '#64748b', fontSize: '13px', padding: '20px' }}>Soldan bir şehir seçin veya yeni şehir ekleyin.</div> : (
                <>
                  <div style={{ display: 'flex', gap: '8px', alignItems: 'center', marginBottom: '12px', flexWrap: 'wrap' }}>
                    <input value={cur.city} onChange={e => patchCur(c => ({ ...c, city: e.target.value }))} style={{ ...fs, flex: 1, minWidth: '140px', fontWeight: '700', fontSize: '15px' }} title="Görünen şehir adı" />
                    <input value={cur.country} onChange={e => patchCur(c => ({ ...c, country: e.target.value }))} placeholder="Ülke" style={{ ...fs, width: '160px' }} />
                    <button onClick={removeCity} style={{ padding: '8px 12px', background: 'rgba(239,68,68,0.12)', border: '1px solid rgba(239,68,68,0.3)', borderRadius: '8px', color: '#ef4444', cursor: 'pointer', fontSize: '12px' }}>🗑 Şehri sil</button>
                  </div>
                  <div style={{ fontSize: '13px', color: '#fb923c', fontWeight: '700', marginBottom: '8px' }}>🍽️ Tavsiye Edilen Restoranlar</div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    {cur.restaurants.map((r, i) => (
                      <div key={i} style={{ padding: '10px', background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.08)', borderRadius: '10px' }}>
                        <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : '2fr 1.4fr 0.9fr', gap: '8px' }}>
                          <input value={r.name || ''} onChange={e => updR(i, 'name', e.target.value)} placeholder="Restoran adı *" style={{ ...fs, fontWeight: '600' }} />
                          <input value={r.cuisine || ''} onChange={e => updR(i, 'cuisine', e.target.value)} placeholder="Mutfak (ör. yerel, balık)" style={fs} />
                          <select value={r.price || ''} onChange={e => updR(i, 'price', e.target.value)} style={fs}>
                            <option value="">Fiyat —</option><option value="€">€ Uygun</option><option value="€€">€€ Orta</option><option value="€€€">€€€ Pahalı</option>
                          </select>
                        </div>
                        <textarea value={r.note || ''} onChange={e => updR(i, 'note', e.target.value)} placeholder="Tavsiye notu (ör. Plov meşhur, akşam rezervasyon önerilir)" rows={2} style={{ ...fs, marginTop: '8px', resize: 'vertical', fontFamily: 'inherit' }} />
                        <div style={{ display: 'flex', gap: '6px', marginTop: '8px', alignItems: 'center' }}>
                          <input value={r.address || ''} onChange={e => updR(i, 'address', e.target.value)} placeholder="Adres (boşsa haritada isimden bulunur)" style={{ ...fs, flex: 1 }} />
                          <button onClick={() => moveR(i, -1)} disabled={i === 0} title="Yukarı" style={small}>↑</button>
                          <button onClick={() => moveR(i, 1)} disabled={i === cur.restaurants.length - 1} title="Aşağı" style={small}>↓</button>
                          <button onClick={() => patchCur(c => ({ ...c, restaurants: c.restaurants.filter((_, j) => j !== i) }))} title="Sil" style={{ ...small, background: 'rgba(239,68,68,0.12)', color: '#ef4444' }}>🗑</button>
                        </div>
                      </div>
                    ))}
                  </div>
                  <div style={{ display: 'flex', gap: '8px', marginTop: '12px', flexWrap: 'wrap', position: 'sticky', bottom: '-14px', background: '#0f2744', padding: '10px 0' }}>
                    <button onClick={() => patchCur(c => ({ ...c, restaurants: [...c.restaurants, { ...EMPTY_REST }] }))} style={{ padding: '10px 14px', background: 'rgba(249,115,22,0.15)', border: '1px solid rgba(249,115,22,0.35)', borderRadius: '8px', color: '#fb923c', cursor: 'pointer', fontSize: '12px', fontWeight: '600' }}>+ Restoran ekle</button>
                    <button onClick={save} disabled={busy || !cur.dirty} style={{ flex: 1, padding: '10px 14px', background: cur.dirty ? 'linear-gradient(135deg, #10b981, #059669)' : 'rgba(255,255,255,0.08)', border: 'none', borderRadius: '8px', color: cur.dirty ? '#fff' : '#64748b', cursor: busy ? 'wait' : cur.dirty ? 'pointer' : 'default', fontSize: '13px', fontWeight: '700' }}>{busy ? '⏳ Kaydediliyor...' : cur.dirty ? `💾 ${cur.city} kaydet` : '✓ Kaydedildi'}</button>
                  </div>
                </>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function CustomerShareModal({ customer, onClose, onSaved, appSettings, showToast }) {
  const c = customer;
  const saved = useMemo(() => safeParseObj(c.shareTrip), [c.shareTrip]);
  const [trip, setTrip] = useState(() => ({ title: '', city: '', country: '', startDate: '', endDate: '', hotelName: '', hotelAddress: '', flights: [], docs: [], ...saved }));
  const [busy, setBusy] = useState('');
  const [ready, setReady] = useState(null); // { link, text, phone }
  const [docType, setDocType] = useState(0);
  const [editMode, setEditMode] = useState(false); // yolculuk/uçuş/otel alanları normalde gizli (belgelerden okunur)
  const token = useRef(c.shareToken || customerLinkSlug(c));
  const up = (patch) => setTrip(t => ({ ...t, ...patch }));
  const inS = { width: '100%', boxSizing: 'border-box', padding: '9px 10px', background: 'rgba(255,255,255,0.06)', border: '1px solid rgba(255,255,255,0.15)', borderRadius: '8px', color: '#e8f1f8', fontSize: '13px', colorScheme: 'dark' };
  const lbl = { display: 'block', fontSize: '11px', color: '#94a3b8', marginBottom: '4px' };
  const sec = { fontSize: '12px', fontWeight: 700, color: '#f59e0b', margin: '14px 0 8px', letterSpacing: '0.5px' };
  const narrow = window.innerWidth < 560;

  const addFiles = async (files) => {
    const list = Array.from(files || []).filter(f => f.size <= 15 * 1024 * 1024);
    if (!list.length) { showToast?.('Dosya seçilmedi (en fazla 15MB)', 'error'); return; }
    setBusy('Yükleniyor…');
    try {
      const { getStorage, ref, uploadBytes, getDownloadURL } = await import('firebase/storage');
      const added = [], found = [], nameWarn = [];
      let hotelFound = null, hotelDocId = '';
      for (const f of list) {
        // Tür belgenin içeriğinden (bilet / biniş kartı / otel…); tanınamazsa seçili tür
        const isPdf = /pdf$/i.test(f.type) || /\.pdf$/i.test(f.name);
        let txt = '';
        if (isPdf) { try { txt = await pdfFileText(f); } catch (e) { /* metin yok */ } }
        const auto = txt ? docTypeOf(txt) : 6;
        const [icon, label] = CUST_DOC_TYPES[auto !== 6 ? auto : docType];
        const docId = generateUniqueId();
        const safe = asciiTr(f.name).replace(/[^\w.\-]+/g, '_').slice(-80);
        const path = `paylasim/${token.current}/${Date.now()}_${safe}`;
        const r = ref(getStorage(), path);
        await uploadBytes(r, f, { contentType: f.type || 'application/octet-stream' });
        added.push({ id: docId, icon, label, url: await getDownloadURL(r), path, name: f.name, addedAt: new Date().toISOString() });
        if (txt) {
          if (icon === '✈️') found.push(...detectFlights(txt).map(x => ({ ...x, docId })));
          if (icon === '🏨') { const h = detectHotel(txt); if (h) { hotelFound = h; hotelDocId = docId; } }
          const k = nameCheck(c, txt); if (k.level === 'warn' || k.level === 'err') nameWarn.push(`${f.name}: ${k.msg}`);
        }
      }
      setTrip(t => {
        const fl = [...(t.flights || [])];
        found.forEach(x => { if (!fl.some(y => sameFlight(y, x))) fl.push(x); });
        fl.sort((a, b) => String(a.ymd).localeCompare(String(b.ymd)));
        const patch = { docs: [...(t.docs || []), ...added], flights: fl };
        if (hotelFound) {
          if (hotelFound.name) patch.hotelName = hotelFound.name;
          if (hotelFound.address) patch.hotelAddress = hotelFound.address;
          if (hotelFound.checkIn) { patch.hotelCheckIn = hotelFound.checkIn; patch.hotelCheckOut = hotelFound.checkOut || ''; }
          patch.hotelDocId = hotelDocId;
          if (hotelFound.checkIn && !t.startDate) patch.startDate = hotelFound.checkIn;
          if (hotelFound.checkOut && !t.endDate) patch.endDate = hotelFound.checkOut;
        }
        // Uçuşlar bulunduysa boş alanları doldur: tarih aralığı ve varış şehri
        if (fl.length) {
          if (!t.startDate) patch.startDate = fl[0].ymd;
          if (!t.endDate) patch.endDate = fl[fl.length - 1].ymd;
          if (!t.city) patch.city = fl[0].toCity;
          if (!t.title) patch.title = `${fl[0].fromCity} → ${fl[0].toCity}`;
        }
        return { ...t, ...patch };
      });
      showToast?.(`📎 ${added.length} belge eklendi${found.length ? ` · ${found.length} uçuş bulundu` : ''}${hotelFound ? ' · otel bilgisi okundu' : ''}`, 'success');
      if (nameWarn.length) setTimeout(() => showToast?.(`İsim kontrolü — ${nameWarn.join(' | ')}`, 'warning'), 400);
    } catch (e) { showToast?.('❌ Yüklenemedi: ' + e.message, 'error'); }
    finally { setBusy(''); }
  };
  const removeDoc = async (d) => {
    const next = tripWithoutDoc(trip, d);
    const lost = (trip.flights || []).length - next.flights.length;
    if (!window.confirm(`"${d.label}" belgesi linkten kaldırılsın mı?${lost ? `\n\nBu belgeden okunan ${lost} uçuş da linkten kalkar.` : ''}${trip.hotelName && !next.hotelName ? '\nOtel bilgisi de kalkar.' : ''}`)) return;
    setTrip(next);
    // Link hemen güncellensin (dosya silindikten sonra linkte kırık belge kalmasın)
    if (c.shareToken || (next.docs || []).length || (next.flights || []).length) {
      try {
        await publishCustomerLink(c, next, token.current, appSettings);
        onSaved?.({ shareToken: token.current, shareTrip: JSON.stringify(next) });
        showToast?.('Belge linkten kaldırıldı', 'success');
      } catch (e) { showToast?.('❌ Link güncellenemedi: ' + e.message, 'error'); return; }
    }
    try { const { getStorage, ref, deleteObject } = await import('firebase/storage'); if (d.path) await deleteObject(ref(getStorage(), d.path)).catch(() => {}); } catch (e) {}
  };
  // Tür değişince belgeyi yeniden oku (otel / bilet bilgisi)
  const changeDocType = async (d, t) => {
    up({ docs: trip.docs.map(x => x.id === d.id ? { ...x, label: t[1], icon: t[0] } : x) });
    if (t[0] !== '🏨' && t[0] !== '✈️') return;
    try {
      const txt = await pdfUrlText(d.url);
      if (t[0] === '🏨') {
        const h = detectHotel(txt);
        if (!h) { showToast?.('Otel bilgisi okunamadı — gerekirse "Elle düzelt"', 'warning'); return; }
        setTrip(tt => ({ ...tt, hotelName: h.name || tt.hotelName, hotelAddress: h.address || tt.hotelAddress, hotelCheckIn: h.checkIn || tt.hotelCheckIn, hotelCheckOut: h.checkOut || tt.hotelCheckOut, hotelDocId: d.id,
          startDate: tt.startDate || h.checkIn || '', endDate: tt.endDate || h.checkOut || '' }));
        showToast?.('🏨 Otel bilgisi okundu', 'success');
      } else {
        const fl = detectFlights(txt).map(x => ({ ...x, docId: d.id }));
        if (!fl.length) return;
        setTrip(tt => { const all = [...(tt.flights || [])]; fl.forEach(x => { if (!all.some(y => sameFlight(y, x))) all.push(x); }); all.sort((a, b) => String(a.ymd).localeCompare(String(b.ymd))); return { ...tt, flights: all }; });
        showToast?.(`✈️ ${fl.length} uçuş okundu`, 'success');
      }
    } catch (e) { showToast?.('Belge yeniden okunamadı: ' + e.message, 'warning'); }
  };
  const setFlight = (i, patch) => up({ flights: trip.flights.map((f, k) => k === i ? { ...f, ...patch } : f) });

  const save = async () => {
    if (!(trip.docs || []).length && !(trip.flights || []).length) { showToast?.('Önce en az bir belge ekleyin', 'warning'); return; }
    setBusy('Kaydediliyor…');
    try {
      const { link, text } = await publishCustomerLink(c, trip, token.current, appSettings);
      onSaved?.({ shareToken: token.current, shareTrip: JSON.stringify(trip) });
      setReady({ link, text, phone: c.phone || '' });
    } catch (e) { showToast?.('❌ Kaydedilemedi: ' + e.message, 'error'); }
    finally { setBusy(''); }
  };

  return (
    <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', zIndex: 3000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '12px' }}>
      <div onClick={e => e.stopPropagation()} style={{ background: '#0f2744', border: '1px solid rgba(34,197,94,0.35)', borderRadius: '14px', padding: '18px', width: '100%', maxWidth: '560px', maxHeight: '92vh', overflowY: 'auto', color: '#e8f1f8' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h3 style={{ margin: 0, fontSize: '16px' }}>🔗 Müşteri Linki — {titleCaseTr(c.firstName)} {titleCaseTr(c.lastName)}</h3>
          <button onClick={onClose} style={{ background: 'none', border: 'none', color: '#94a3b8', fontSize: '22px', cursor: 'pointer' }}>×</button>
        </div>
        <p style={{ margin: '4px 0 0', fontSize: '11px', color: '#64748b' }}>Bilet, otel belgesi, vize… tek linkte. Belge ekledikçe aynı link güncellenir.{c.shareToken ? ' Bu müşterinin linki daha önce oluşturuldu.' : ''} 🔐 Müşteri ilk açılışta kendi 4 haneli PIN'ini belirler; PIN müşteri kartında görünür.</p>

        {ready ? (
          <div style={{ marginTop: '14px' }}>
            <label style={lbl}>✏️ Gönderilecek mesaj</label>
            <textarea value={ready.text} onChange={e => setReady({ ...ready, text: e.target.value })} rows={7} style={{ ...inS, lineHeight: 1.45, fontFamily: 'inherit', resize: 'vertical' }} />
            <label style={{ ...lbl, marginTop: '8px' }}>📱 WhatsApp numarası (müşteri veya firma yetkilisi)</label>
            <input value={ready.phone} onChange={e => setReady({ ...ready, phone: e.target.value })} placeholder="+90 5xx xxx xx xx" style={inS} />
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', marginTop: '12px' }}>
              <a href={`https://wa.me/${formatWhatsAppPhone(ready.phone) || ''}?text=${encodeURIComponent(ready.text)}`} target="_blank" rel="noopener noreferrer" style={{ padding: '12px', background: 'linear-gradient(135deg, #22c55e, #16a34a)', borderRadius: '10px', color: '#fff', fontWeight: 700, textAlign: 'center', textDecoration: 'none' }}>💬 WhatsApp'tan gönder</a>
              <button onClick={async () => { try { await navigator.clipboard.writeText(ready.text); showToast?.('Mesaj kopyalandı', 'success'); } catch { showToast?.('Kopyalanamadı', 'error'); } }} style={{ padding: '10px', background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.15)', borderRadius: '8px', color: '#e8f1f8', cursor: 'pointer' }}>📋 Mesajı kopyala</button>
              <button onClick={() => window.open(ready.link, '_blank')} style={{ padding: '10px', background: 'none', border: 'none', color: '#94a3b8', cursor: 'pointer', fontSize: '12px' }}>👁️ Müşterinin göreceği sayfayı aç</button>
              <button onClick={() => setReady(null)} style={{ padding: '8px', background: 'none', border: 'none', color: '#64748b', cursor: 'pointer', fontSize: '12px' }}>← Belgelere geri dön</button>
            </div>
          </div>
        ) : (<>
          <div style={sec}>BELGELER</div>
          {(trip.docs || []).map(d => (
            <div key={d.id} style={{ display: 'flex', alignItems: 'center', gap: '8px', padding: '8px 10px', background: 'rgba(255,255,255,0.04)', borderRadius: '8px', marginBottom: '6px', fontSize: '13px' }}>
              <span>{d.icon}</span>
              <select value={d.label} onChange={e => { const t = CUST_DOC_TYPES.find(x => x[1] === e.target.value); changeDocType(d, t); }} style={{ ...inS, width: 'auto', padding: '4px 6px', fontSize: '12px' }}>
                {CUST_DOC_TYPES.map(([, l]) => <option key={l} value={l} style={{ background: '#0c1929' }}>{l}</option>)}
              </select>
              <a href={d.url} target="_blank" rel="noopener noreferrer" style={{ flex: 1, minWidth: 0, color: '#94a3b8', fontSize: '11px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{d.name || 'belge'}</a>
              <button onClick={() => removeDoc(d)} title="Linkten kaldır" style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer' }}>🗑</button>
            </div>
          ))}
          <div style={{ display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' }}>
            <select value={docType} onChange={e => setDocType(+e.target.value)} style={{ ...inS, width: 'auto' }}>
              {CUST_DOC_TYPES.map(([i, l], k) => <option key={l} value={k} style={{ background: '#0c1929' }}>{i} {l}</option>)}
            </select>
            <label style={{ padding: '9px 14px', background: 'rgba(59,130,246,0.18)', border: '1px solid rgba(59,130,246,0.4)', borderRadius: '8px', color: '#60a5fa', cursor: busy ? 'wait' : 'pointer', fontSize: '13px', fontWeight: 600 }}>
              {busy || '📎 Dosya ekle (PDF / görsel)'}
              <input type="file" multiple accept="application/pdf,image/*" disabled={!!busy} style={{ display: 'none' }} onChange={e => { addFiles(e.target.files); e.target.value = ''; }} />
            </label>
          </div>

          {/* Belgelerden okunanlar — elle giriş gerekmez; nadiren yanlış okunursa "Elle düzelt" */}
          <div style={sec}>LİNKTE GÖRÜNECEK <span style={{ color: '#64748b', fontWeight: 400 }}>(belgelerden otomatik okunur)</span></div>
          <div style={{ padding: '10px 12px', background: 'rgba(255,255,255,0.04)', borderRadius: '10px', fontSize: '12.5px', lineHeight: 1.7, color: '#cbd5e1' }}>
            {(trip.flights || []).length
              ? (trip.flights || []).map((f, i) => <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '6px' }}><span style={{ flex: 1 }}>✈️ <b>{f.code}</b> · {f.ymd ? formatDate(f.ymd) : 'tarih yok'} · {f.from || '?'} {f.dep || ''} → {f.to || '?'} {f.arr || ''}</span><button onClick={() => up({ flights: trip.flights.filter((_, k) => k !== i) })} title="Bu uçuşu linkten çıkar (kaydedince)" style={{ background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer', fontSize: '12px' }}>🗑</button></div>)
              : <div style={{ color: '#64748b' }}>✈️ Uçuş yok — bilet yüklenince otomatik eklenir</div>}
            {trip.hotelName
              ? <div>🏨 <b>{trip.hotelName}</b>{trip.hotelCheckIn ? ` · ${formatDate(trip.hotelCheckIn)}${trip.hotelCheckOut ? ' – ' + formatDate(trip.hotelCheckOut) : ''}` : ''}{trip.hotelAddress ? <span style={{ color: '#94a3b8' }}> · {trip.hotelAddress}</span> : ''}</div>
              : <div style={{ color: '#64748b' }}>🏨 Otel yok — otel giriş belgesi yüklenince otomatik eklenir</div>}
          </div>
          {((trip.flights || []).length > 0 || trip.hotelCheckIn) && <TravelCheckBox c={c} trip={trip} />}
          <button onClick={() => setEditMode(v => !v)} style={{ marginTop: '8px', padding: '6px 12px', background: 'none', border: '1px dashed rgba(255,255,255,0.18)', borderRadius: '8px', color: '#94a3b8', cursor: 'pointer', fontSize: '12px' }}>{editMode ? '▲ Elle düzeltmeyi kapat' : '✏️ Elle düzelt (yanlış okunduysa)'}</button>
          {editMode && (<>
          <div style={sec}>YOLCULUK</div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px' }}>
            <div style={{ gridColumn: '1 / -1' }}><label style={lbl}>Başlık</label><input value={trip.title} onChange={e => up({ title: e.target.value })} placeholder="Örn. Frankfurt İş Seyahati" style={inS} /></div>
            <div><label style={lbl}>Şehir</label><input value={trip.city} onChange={e => up({ city: e.target.value })} placeholder="Frankfurt" style={inS} /></div>
            <div><label style={lbl}>Ülke</label>
              <select value={trip.country} onChange={e => up({ country: e.target.value })} style={inS}>
                <option value="" style={{ background: '#0c1929' }}>Seçin…</option>
                {tourCountries.map(x => <option key={x} value={x} style={{ background: '#0c1929' }}>{x}</option>)}
              </select></div>
            <div><label style={lbl}>Gidiş</label><input type="date" value={trip.startDate} onChange={e => up({ startDate: e.target.value })} style={inS} /></div>
            <div><label style={lbl}>Dönüş</label><input type="date" value={trip.endDate} onChange={e => up({ endDate: e.target.value })} style={inS} /></div>
          </div>

          <div style={sec}>UÇUŞLAR <span style={{ color: '#64748b', fontWeight: 400 }}>(biletten otomatik bulunur — linkte canlı takip)</span></div>
          {(trip.flights || []).map((f, i) => (
            <div key={i} style={narrow
              ? { display: 'grid', gridTemplateColumns: '1fr 1fr auto', gridTemplateAreas: '"c d x" "f t x"', gap: '6px', marginBottom: '12px', alignItems: 'center' }
              : { display: 'grid', gridTemplateColumns: '80px 1fr 1fr 1fr auto', gridTemplateAreas: '"c d f t x"', gap: '6px', marginBottom: '6px', alignItems: 'center' }}>
              <input value={f.code} onChange={e => setFlight(i, { code: e.target.value.toUpperCase() })} placeholder="TK1590" style={{ ...inS, gridArea: 'c' }} />
              <input type="date" value={f.ymd || ''} onChange={e => setFlight(i, { ymd: e.target.value })} style={{ ...inS, gridArea: 'd' }} />
              <input value={`${f.from || ''}${f.dep ? ' ' + f.dep : ''}`} onChange={e => { const [a, b] = e.target.value.split(' '); setFlight(i, { from: (a || '').toUpperCase().slice(0, 3), dep: b || '' }); }} placeholder="Kalkış: IST 08:30" style={{ ...inS, gridArea: 'f' }} />
              <input value={`${f.to || ''}${f.arr ? ' ' + f.arr : ''}`} onChange={e => { const [a, b] = e.target.value.split(' '); setFlight(i, { to: (a || '').toUpperCase().slice(0, 3), arr: b || '' }); }} placeholder="Varış: FRA 10:45" style={{ ...inS, gridArea: 't' }} />
              <button onClick={() => up({ flights: trip.flights.filter((_, k) => k !== i) })} style={{ gridArea: 'x', background: 'none', border: 'none', color: '#ef4444', cursor: 'pointer' }}>🗑</button>
            </div>
          ))}
          <button onClick={() => up({ flights: [...(trip.flights || []), { code: '', ymd: trip.startDate || '', from: '', to: '', dep: '', arr: '' }] })} style={{ padding: '6px 12px', background: 'rgba(255,255,255,0.06)', border: '1px dashed rgba(255,255,255,0.2)', borderRadius: '8px', color: '#94a3b8', cursor: 'pointer', fontSize: '12px' }}>＋ Uçuş ekle</button>

          <div style={sec}>OTEL <span style={{ color: '#64748b', fontWeight: 400 }}>(linkte adres + yol tarifi)</span></div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px' }}>
            <input value={trip.hotelName} onChange={e => up({ hotelName: e.target.value })} placeholder="Otel adı" style={inS} />
            <input value={trip.hotelAddress} onChange={e => up({ hotelAddress: e.target.value })} placeholder="Adres" style={inS} />
            <div><label style={lbl}>Otel giriş</label><input type="date" value={trip.hotelCheckIn || ''} onChange={e => up({ hotelCheckIn: e.target.value })} style={inS} /></div>
            <div><label style={lbl}>Otel çıkış</label><input type="date" value={trip.hotelCheckOut || ''} onChange={e => up({ hotelCheckOut: e.target.value })} style={inS} /></div>
          </div>

          </>)}

          <button onClick={save} disabled={!!busy} style={{ width: '100%', marginTop: '16px', padding: '12px', background: 'linear-gradient(135deg, #22c55e, #16a34a)', border: 'none', borderRadius: '10px', color: '#fff', fontWeight: 700, fontSize: '14px', cursor: busy ? 'wait' : 'pointer' }}>
            {busy || (c.shareToken ? '💾 Kaydet ve linki güncelle' : '🔗 Linki oluştur')}
          </button>
        </>)}
      </div>
    </div>
  );
}

// ===== TOPLU BELGE YÜKLEME (tek yükleme yeri) =====
// Biletçi/otelci bilet, biniş kartı, otel belgesi… PDF'lerini buraya bırakır. Sistem her sayfadaki yolcu adını
// tüm müşterilerle eşleştirir, belge türünü metinden tanır, çok sayfalı PDF'i kişi başı böler ve her kişinin
// müşteri linkine ekler (link yoksa oluşturur). Biletten uçuşlar ve tarihler de linke işlenir.
const docTypeOf = (text) => {
  const t = asciiTr(String(text || '')).toUpperCase();
  if (/BOARDING\s*PASS|BINIS\s*KART|BOARDING\s*TIME|GATE\s*CLOSES/.test(t)) return 1;          // 🛫 Biniş Kartı
  // Bilet önce: uçak biletlerinde de "online check-in", bazen "hotel" reklamı geçer — otel sanılmasın
  const flightCode = /\b(?:TK|PC|VF|XQ|XC|J2|LH|AF|KL|BA|EK|QR|FZ|W6|FR|U2|SU|A3|OS|LX|LO|KC|HY|G9|SV|MS|RJ|AZ|IB|VY|TP|SK|AY)\s?\d{2,4}\b/.test(t);
  if (/E-?\s?TICKET|ELECTRONIC\s*TICKET|ELEKTRONIK\s*BILET|TICKET\s*(NUMBER|NO|DETAILS?)|BILET\s*(NUMARASI|BILGI|DETAY)|ITINERARY|ETKT|BOOKING\s*REF|REZERVASYON\s*KODU|\bPNR\b|PASSENGER|YOLCU\s*(ADI|BILGI)|FLIGHT\s*(NO|NUMBER|DETAILS?)|UCUS\s*(NO|BILGI|DETAY)|DEPARTURE\s*TIME|KALKIS\s*SAATI|BAGGAGE|BAGAJ/.test(t)
    && (flightCode || /FLIGHT|UCUS|AIRLINES?|HAVAYOLU|AIRPORT|HAVALIMANI|\([A-Z]{3}\)/.test(t))) return 0;      // ✈️ Uçak Bileti
  if (/HOTEL|OTEL|VOUCHER|ACCOMMODATION|KONAKLAMA|ROOM\s*TYPE|ODA\s*TIPI|GUEST\s*NAME|MISAFIR/.test(t)) return 2; // 🏨 Otel Belgesi
  if (flightCode && /FLIGHT|UCUS|AIRLINES?|HAVAYOLU|AIRPORT|HAVALIMANI|CHECK-?\s?IN/.test(t)) return 0; // ✈️ (etiketsiz bilet)
  if (/INSURANCE|SIGORTA|POLICE\s*NO|POLICY\s*(NUMBER|NO)/.test(t)) return 4;                    // 🛡️ Sigorta
  if (/\bVISA\b|\bVIZE\b|SCHENGEN/.test(t)) return 3;                                           // 🛂 Vize
  return 6;                                                                                       // 📄 Diğer
};
// Müşteri ad-soyad kelimeleri (eşleştirme dizini) — en az 2 kelime (tek kelimelik isimler yanlış eşleşir)
const buildNameIndex = (customers) => (customers || []).map(c => ({ c, w: [...nameWords(`${c.firstName || ''} ${c.lastName || ''}`)].filter(x => x.length > 1) })).filter(x => x.w.length >= 2);
// Metindeki kelimelere göre müşterileri bul; en çok kelimesi tutan(lar) döner
const matchCustomers = (index, words) => {
  const hits = index.filter(x => x.w.every(w => words.has(w)) || (x.w.length >= 3 && words.has(x.w[0]) && words.has(x.w[x.w.length - 1])));
  if (hits.length < 2) return hits.map(h => h.c);
  const score = (h) => h.w.filter(w => words.has(w)).length;
  const max = Math.max(...hits.map(score));
  return hits.filter(h => score(h) === max).map(h => h.c);
};

// 🔍 Mükerrer / TC kontrolü — tüm müşterileri tarar
function DuplicateScanModal({ customers, onOpen, onClose }) {
  const [tab, setTab] = useState('tcName');
  const data = useMemo(() => {
    const nm = (c) => normalizeTr(`${c.firstName || ''} ${c.lastName || ''}`).replace(/\s+/g, ' ');
    const group = (keyFn) => {
      const m = new Map();
      (customers || []).forEach(c => { const k = keyFn(c); if (!k) return; if (!m.has(k)) m.set(k, []); m.get(k).push(c); });
      return [...m.entries()].filter(([, arr]) => arr.length > 1);
    };
    const byTc = group(c => { const t = String(c.tcKimlik || '').trim(); return t.length >= 6 ? t : ''; });
    const tcName = byTc.filter(([, arr]) => new Set(arr.map(nm)).size > 1);
    const tcSame = byTc.filter(([, arr]) => new Set(arr.map(nm)).size === 1);
    const pp = new Map();
    (customers || []).forEach(c => safeParseJSON(c.passports).forEach(p => { const k = String(p.passportNo || '').trim().toUpperCase().replace(/\s/g, ''); if (k.length < 6) return; if (!pp.has(k)) pp.set(k, new Set()); pp.get(k).add(c); }));
    const passport = [...pp.entries()].filter(([, set]) => set.size > 1).map(([k, set]) => [k, [...set]]);
    const nameBirth = group(c => (c.birthDate && nm(c) ? `${nm(c)}|${c.birthDate}` : ''));
    const badTc = (customers || []).filter(c => String(c.tcKimlik || '').trim() && !isValidTc(c.tcKimlik));
    return { tcName, tcSame, passport, nameBirth, badTc };
  }, [customers]);
  const tabs = [
    ['tcName', '🚨 Aynı TC, farklı isim', data.tcName.length],
    ['tcSame', 'Aynı TC, aynı isim', data.tcSame.length],
    ['passport', 'Aynı pasaport no', data.passport.length],
    ['nameBirth', 'Aynı ad + doğum', data.nameBirth.length],
    ['badTc', 'Geçersiz TC', data.badTc.length],
  ];
  const ppList = (c) => safeParseJSON(c.passports).map(p => p.passportNo).filter(Boolean).join(', ');
  const row = (c) => (
    <div key={c._docId || c.id} style={{ display: 'flex', alignItems: 'center', gap: '10px', padding: '6px 0', fontSize: '12px', color: '#e8f1f8', flexWrap: 'wrap' }}>
      <span style={{ flex: 1, minWidth: '200px' }}><b>{titleCaseTr(`${c.firstName || ''} ${c.lastName || ''}`)}</b> · TC {c.tcKimlik || '—'}{c.tcKimlik && !isValidTc(c.tcKimlik) ? ' ⚠️' : ''} · Doğum {c.birthDate ? formatDate(c.birthDate) : '—'} · Pasaport {ppList(c) || '—'}{c.createdAt ? ` · Kayıt ${formatDate(c.createdAt)}` : ''}</span>
      <button type="button" onClick={() => onOpen(c)} style={{ padding: '5px 12px', background: 'rgba(59,130,246,0.2)', border: '1px solid rgba(59,130,246,0.4)', borderRadius: '8px', color: '#60a5fa', cursor: 'pointer', fontWeight: '600', fontSize: '12px', fontFamily: 'inherit' }}>Aç</button>
    </div>
  );
  const groups = tab === 'badTc' ? null : data[tab];
  return (
    <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '16px' }}>
      <div onClick={e => e.stopPropagation()} style={{ background: '#0f1d2e', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '14px', width: '100%', maxWidth: '900px', maxHeight: '90vh', display: 'flex', flexDirection: 'column' }}>
        <div style={{ padding: '16px 20px', borderBottom: '1px solid rgba(255,255,255,0.08)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <div style={{ fontSize: '16px', fontWeight: '700', color: '#fff' }}>🔍 Mükerrer / TC Kontrolü</div>
            <div style={{ fontSize: '12px', color: '#94a3b8' }}>{(customers || []).length} müşteri tarandı · TC eşsizdir: aynı TC farklı isimde ise TC veya isim hatalıdır</div>
          </div>
          <button type="button" onClick={onClose} style={{ background: 'none', border: 'none', color: '#94a3b8', fontSize: '22px', cursor: 'pointer' }}>✕</button>
        </div>
        <div style={{ display: 'flex', gap: '6px', padding: '12px 20px', flexWrap: 'wrap', borderBottom: '1px solid rgba(255,255,255,0.08)' }}>
          {tabs.map(([id, label, n]) => (
            <button key={id} type="button" onClick={() => setTab(id)} style={{ padding: '7px 12px', borderRadius: '8px', fontSize: '12px', fontWeight: '600', cursor: 'pointer', fontFamily: 'inherit', border: '1px solid', borderColor: tab === id ? '#f59e0b' : 'rgba(255,255,255,0.12)', background: tab === id ? 'rgba(245,158,11,0.15)' : 'transparent', color: n ? (tab === id ? '#fbbf24' : '#e8f1f8') : '#64748b' }}>{label} ({n})</button>
          ))}
        </div>
        <div style={{ padding: '8px 20px 20px', overflowY: 'auto' }}>
          {tab === 'badTc'
            ? (data.badTc.length ? <><div style={{ fontSize: '12px', color: '#94a3b8', margin: '8px 0' }}>11 hane değil ya da TC doğrulama basamakları tutmuyor — yanlış girilmiş/okunmuş olabilir.</div>{data.badTc.map(row)}</> : <div style={{ padding: '30px', textAlign: 'center', color: '#10b981' }}>✅ Sorun yok</div>)
            : (groups.length ? groups.map(([k, arr]) => (
              <div key={k} style={{ marginTop: '12px', padding: '10px 14px', background: tab === 'tcName' ? 'rgba(239,68,68,0.08)' : 'rgba(255,255,255,0.03)', border: `1px solid ${tab === 'tcName' ? 'rgba(239,68,68,0.35)' : 'rgba(255,255,255,0.08)'}`, borderRadius: '10px' }}>
                <div style={{ fontSize: '11px', color: '#94a3b8', fontWeight: '600' }}>{tab === 'passport' ? `Pasaport ${k}` : tab === 'nameBirth' ? 'Aynı ad-soyad + doğum tarihi' : `TC ${k}`} · {arr.length} kayıt</div>
                {arr.map(row)}
              </div>
            )) : <div style={{ padding: '30px', textAlign: 'center', color: '#10b981' }}>✅ Sorun yok</div>)}
        </div>
      </div>
    </div>
  );
}

// 🛏️ Otel oda kontenjanı: Single / Double / Twin
const HOTEL_ROOM_KINDS = ['Single', 'Double', 'Twin'];
const roomKindOf = (rt) => {
  const s = normalizeTr(rt);
  if (/twin|twn/.test(s)) return 'Twin';
  if (/sing|sgl|tek/.test(s)) return 'Single';
  if (/doub|dbl|cift|dubl/.test(s)) return 'Double';
  return '';
};
// Her oda tipi için en yoğun gecede dolu oda sayısı (1 rezervasyon = 1 oda; iptaller sayılmaz).
// Farklı tarihlerdeki rezervasyonlar üst üste binmediği için toplam değil, gece bazında bakılır.
const hotelRoomUsage = (h) => {
  const per = {};
  (h?.reservations || []).filter(r => !r.cancelled).forEach(r => {
    const k = roomKindOf(r.roomType);
    const a = /^\d{4}-\d{2}-\d{2}/.test(String(r.checkIn || '')) ? new Date(`${String(r.checkIn).slice(0, 10)}T12:00:00Z`) : null;
    const b = /^\d{4}-\d{2}-\d{2}/.test(String(r.checkOut || '')) ? new Date(`${String(r.checkOut).slice(0, 10)}T12:00:00Z`) : null;
    if (!k || !a || !b) return;
    for (let d = new Date(a), i = 0; d < b && i < 400; d.setUTCDate(d.getUTCDate() + 1), i++) {
      const key = d.toISOString().slice(0, 10);
      (per[k] = per[k] || {})[key] = (per[k][key] || 0) + 1;
    }
  });
  const out = {};
  HOTEL_ROOM_KINDS.forEach(k => {
    let max = 0, day = '';
    Object.entries(per[k] || {}).forEach(([dd, c]) => { if (c > max || (c === max && dd < day)) { max = c; day = dd; } });
    out[k] = { max, day };
  });
  return out;
};

