      const totals = {}; items.forEach(it => { const k = code(it.currency || '€'); totals[k] = (totals[k] || 0) + (parseFloat(it.amount) || 0); });
      const curCodes = Object.keys(totals); const curCode = curCodes[0] || 'EUR';
      const doc = new jsPDF();
